quests[12647] = { id = 12647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to the Suffering", description = "My body is too far gone now, {name}. It is only a matter of time before a new prophet is elevated and finishes what the other began.\n\nI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.\n\nUse the incense and do me the kindness of putting an end to my suffering.\n\nI apologize if I fight back. Even for me, the will to survive is strong.", sourceObjective = "The Spirit of Rhunok has asked you to use the Tormentor's Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with.\n\nIf for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.", progress = "If you do not put an end to my suffering soon, {name}, all may be lost.", completion = "You've done what had to be done and honored me in the process.\n\nI give you my deepest thanks, {name}. I only hope that you and Har'koa will be able to help the others.", sourceObjectiveStatus = "unverified-source-field" }
quests[12648] = { id = 12648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing Down", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.", sourceObjective = "Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Well, {name}?\n\nDid you purchase that flask?", completion = "So? How are you enjoying scourge life?\n\nBelieve me, it's not all it's cracked up to be....", sourceObjectiveStatus = "unverified-source-field" }
quests[12649] = { id = 12649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suit Up!", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.", sourceObjective = "Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Well, {name}?\n\nDid you purchase that flask?", completion = "So? How are you enjoying Scourge life?\n\nBelieve me, it's not all it's cracked up to be....", sourceObjectiveStatus = "unverified-source-field" }
quests[12650] = { id = 12650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plundering Their Own", description = "There is another altar nearby where there are artifacts to be saved.\n\nIt is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak'Mabwa, have already plundered their own holy site.\n\n{class}, I would be appreciative if you could rescue those artifacts from their undeserving hands.", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to recover 7 Rhunokian Artifacts.", progress = "There is no comprehending the Drakkari. They are brutal savages who have sunk to a new low.", completion = "Let me look at those.\n\n<The chronicler examines the artifacts that you have recovered.>\n\nHmph, I'd say that we're lucky you liberated these when you did, {class}.\n\nHow very interesting. This artifact here depicts the events of the Sundering. There was a time when Northrend was the far northern portion of Kalimdor.\n\nBut after the Sundering, the land broke off, eventually becoming Northrend.\n\nThis, of course, is why we see Drakkari in the southern continents as well as here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12651] = { id = 12651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lakeside Landing", description = "When the trouble with the Venture Company started, I asked Marvin Wobblesprocket and his wife, Tamara, to take their flying machines east to River's Heart. I asked them to setup a small camp there so that we could use them as a relay to fly in supplies and survey the area.\n\nThey should have arrived by now and started setting up. River's Heart is near the center of the basin where the rivers converge. Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the best spot.", sourceObjective = "Speak with Tamara Wobblesprocket at Lakeside Landing.", completion = "So, Hemet sent you? We were just about to let him know that we've gotten things up and running here. Please forgive Marvin if he seems to be ignoring you, but he gets very absorbed in his work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12652] = { id = 12652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feedin' Da Goolz", description = "Git o'er heer, gool! Yeh, I talkin' to yoo.\n\nIt feedin' time now. Gotta git da grub ta all da gools!\n\nSpeshal grub dis time! Bowels an' brainz bowl... num, num, num.\n\nJus drop da bowl nexta da gool. Gud way ta make frenz.\n\nYoo got goolfrenz? Ha, ha, hah!", sourceObjective = "Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.", progress = "Yoo dun feed da goolz?", completion = "Num num!", sourceObjectiveStatus = "unverified-source-field" }
quests[12653] = { id = 12653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Har'koa", description = "And now it is time for you to return to the leopard goddess. Somehow I sense that she has other plans for you.\n\nTell her that no matter what, we are eternal.", sourceObjective = "Speak with Har'koa at the Altar of Har'koa.", completion = "<The cat goddess howls in pain.>\n\nMy spirit cries out in grief at the loss of another friend. But fear not, he will return and his spirit will live on forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[12654] = { id = 12654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Part-time Hunter", description = "When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.\n\nI wanted to take down a ferocious lion named Pitch. He's said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect!", sourceObjective = "Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing.", progress = "Did you find Pitch?", completion = "You got it! Now all I have to do is make a trophy out of it. That'll be the hard part -- finding a way to preserve it so that Hemet doesn't have a good laugh at my expense.", sourceObjectiveStatus = "unverified-source-field" }
quests[12655] = { id = 12655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Rhuk", description = "There is another god of Zul'Drak that is being neglected.\n\nZim'Rhuk's statue lies directly to the north. Known as \"The Wise One\", Zim'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them.\n\nAvoid the guardians and give the Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.", sourceObjective = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk.", progress = "<You sense that Zim'Rhuk does not trust you. He is attempting to call out to one of his guardians.>", completion = "<Zim'Rhuk acknowledges the offerings you intend to place before him, though he knows that you took them from the corpses of others.>\n\n<If you give the offerings to him, he reluctantly agrees to grant you his blessing.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12656] = { id = 12656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Rhuk", progress = "<Zim'Rhuk is impressed and frustrated that once more you seem to have dodged his guardians. At least for now.>\n\n<Place the offerings before him and he will grant you his blessing again.>", completion = "<Zim'Rhuk forces an image into your mind of one of his guardians squishing you beneath its foot. Perhaps you should attempt to appease Zim'Rhuk with more offerings.>" }
quests[12657] = { id = 12657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might Of The Scourge", description = "Listen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the Scourge without reprisal!\n\nAs you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault.\n\nAnd when the Crusade has been dealt with, we will finish off the Argent Dawn.", sourceObjective = "The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold.\n\nUse the glowing transporter behind The Lich King to reach Highlord Darion Mograine in the Hall of Command.", completion = "The horns of war will soon echo across this land, waking the dead and calling forth the Scourge war machine. Woe unto those that would stand in our way!\n\nYou and your brethren will lead the charge, {name}. When next I look upon the Scarlet lands, my sight will be obscured by the legions of Acherus. The march upon New Avalon begins now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12658] = { id = 12658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Pet Roc", description = "Dorian's had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!\n\nNo, not a juvenile drake. I don't want a pet capable of biting my hand off!\n\nHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there's a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.", sourceObjective = "Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost.", progress = "Do you have those eggs?", completion = "Oh, these are very nice! I've gotten so tired of robotic squirrels and chickens for company. It'll be wonderful to have a pet whose joints won't require oiling!", sourceObjectiveStatus = "unverified-source-field" }
quests[12659] = { id = 12659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalps!", description = "I thinkin' it be time to do some scalpin', mon!\n\nThe trolls at Heb'Drakkar to the northeast should do nicely. With their fancy bats and attackin' us, they got it comin'!\n\nAhunae even give you his own knife so that you do the job right.", sourceObjective = "Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls.\n\nThe scalper reminds you that you should loot them first.", completion = "Aw, me thinkin' that too funny.\n\n{name} is my kind of {race}!\n\nYou still got my knife?", sourceObjectiveStatus = "unverified-source-field" }
quests[12660] = { id = 12660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Destruction", description = "The Lich King's lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this.\n\nGo to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.", sourceObjective = "The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives.", progress = "Is it done, {name}?", completion = "I thank you, {race}.  You're proving to be a worthy ally.", sourceObjectiveStatus = "unverified-source-field" }
quests[12661] = { id = 12661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Voltarus", description = "By now you've probably guessed the details of my plan.\n\nWe're using the Scourge's interest in you against them. You're going undercover. I know it's likely a death sentence, but if we do nothing your death is a certainty.\n\nTravel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander.\n\nWhen you've completed your mission, blow this horn and I'll fly to your location to receive your report.", sourceObjective = "Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", completion = "Well, now... I must admit I'm more than a little surprised to see you, {name}.\n\nTell me what you've learned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12662] = { id = 12662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down Heb'Jin", description = "<Dagoda looks at Ahunae and sighs.>\n\nYou want to really deal with Heb'Drakkar? Collecting scalps isn't going to get the job done. You have to take out their leader, Heb'Jin.\n\nThe problem is, he's up on the bat rookery goading his forces on.\n\nBang his drum and I guarantee that he'll fly down. That's when you kill him.\n\nYou can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won't have to fight both of them.", sourceObjective = "Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin.", completion = "You did it!\n\n<Dagoda gives you a big kiss on the cheek.>\n\nYou have no idea how much of a relief that is to me! Defending against trolls on all sides is really putting a strain on us. Not to mention his incessant yelling.\n\nPlease, {name}, take your pick of what we have to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12663] = { id = 12663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunited", description = "{name}!\n\nYa musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud.\n\nWe come such a long way, you and I, and now we be servin' da Lich King together.\n\nStick with me and big things be comin, mon. Big things... but first, we need to be gettin' ya caught up. So much been happenin' since I saw ya last.\n\nGo speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell ya all ya be needin' ta know.", sourceObjective = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", progress = "You an' me gunna take Gundrak, mon.", completion = "So, now ya be seein' what we be up against, mon.\n\nGo down, take some time ta learn da land, prepare some strategy. \n\nI'll be havin' some tasks for ya soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12664] = { id = 12664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Horizon", description = "Ahh, another supplicant answerin' da Lich King's call.\n\n<Drakuru sniffs you.>\n\nFreshly scourged, eh? Ya still be reekin' of da living!\n\nLong be da line of dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself worthy of wieldin' true power.\n\nLookin' down over Zul'Drak, I sensed potential in ya. I ordered your - invitation.\n\nDa rest be up ta you....\n\nGo an' speak ta Gorebag for a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.", sourceObjective = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", progress = "Have ya taken in da battlefield yet, mon?", completion = "So, now ya be seein' what we be up against, mon.\n\nI want ya ta go down, learn da land, mingle with yer bretheren. Prepare yourself...\n\nSoon, dere be much for ya to do. Don't ya be disappointin' me!", sourceObjectiveStatus = "unverified-source-field" }
quests[12665] = { id = 12665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Sense a Disturbance", description = "There's something wrong with Quetz'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures.\n\nI'm going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz'lun.\n\nMy child will see you safely back to me. Just keep your eyes open.\n\nWhen you are ready, ask and I will call one of my kittens for you.", sourceObjective = "Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun.\n\nReturn to her at the Altar of Har'koa once you have done so.", progress = "What seems to be the delay, {name}?", completion = "Thank you for bringing my kitten back safely.\n\nDeep down I knew it. I wanted to deny it, but your eyes have revealed the truth.\n\nNevertheless, I sense something else. All is not as it seems.", sourceObjectiveStatus = "unverified-source-field" }
quests[12666] = { id = 12666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for the Underworld", description = "Quetz'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her.\n\nLuckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them.\n\nBring the adornments to me and I'll draw upon their energy to enable you to cross over into Quetz'lun's underworld nightmare.", sourceObjective = "Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa.", progress = "I never imagined that it would come to this. The Drakkari are truly lost.", completion = "<The leopard goddess looks saddened at the collection of holy symbols that you have brought before her.>\n\nThere was a time when these meant something. Let's see if we can put them to better use.", sourceObjectiveStatus = "unverified-source-field" }
quests[12667] = { id = 12667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Wind Serpent Goddess", description = "You are prepared, but I'm not certain that you're ready for what is to come.\n\nWhen you cross back over into Quetz'lun's altar area, you will enter the realm of the dead. From what I can feel of it, it's not going to be pleasant.\n\nTry not to be distracted by what you see in there. Simply head for the altar building and seek out Quetz'lun's Spirit.", sourceObjective = "Seek Quetz'lun's Spirit at the Altar of Quetz'lun.", completion = "{race} worm. Tell me why I should not annihilate you where you stand?", sourceObjectiveStatus = "unverified-source-field" }
quests[12668] = { id = 12668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foundation for Revenge", description = "I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.\n\nYou do still want to live, yes?\n\nAs you have seen, my devotees are enjoying their stay here, but now it's time for them to make final restitution.\n\nDo me the smallest of favors if you would, {name}. Lure them near my soul fonts and then put an end to their existences.\n\nThey taste so delicious, and their sacrifice will not go in vain, I can assure you.", sourceObjective = "Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts.\n\nOnly after you have accomplished this should you return to her at the Altar of Quetz'lun.", progress = "Why do you return when your task is not yet complete? Do you not realize that I can destroy you with but a thought?\n\nGo now, little {race}. Complete that which I commanded of you!", completion = "Exquisite. Perhaps you will be of some use after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12669] = { id = 12669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Far, So Bad", description = "Everything you've reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions.\n\nReturn to him and do as he says. Do whatever you must to appear sincere, {name}. A great deal is riding upon your performance.\n\nThis time I'm adding an additional assignment: While you're in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.", sourceObjective = "Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.\n\nWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Please, {name}, tell me you haven't blown your cover....", completion = "Nice work, {name}!\n\nDiluting those cauldrons will not only save lives, it will slow the growth of the Scourge in this region.\n\nNow come, tell me what you've learned of Drakuru's strategy in Zul'Drak.", sourceObjectiveStatus = "unverified-source-field" }
quests[12670] = { id = 12670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Harvest", description = "Below Acherus stands Death's Breach, the staging point for our assault upon the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side of this platform, and report to Prince Valanar. Do as he says and you may live to see these lands fall before us.", sourceObjective = "Report to Prince Valanar at Death's Breach.", completion = "Do you smell it?\n\n<Valanar sniffs at the air.>\n\nFresh meat... The scent of Scarlet Crusader wafts through the air.\n\n<Valanar salivates.>\n\nApologies, {class}, I'm sure you're not interested in my choice of fine cuisine. You are here to work! To lead the charge! Yes... I know. The Lich King has told me all that I need to know about you, {name}.\n\nThe time for bloodshed is now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12671] = { id = 12671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconnaissance Flight", description = "It's about time we had planes up and running in this place.  The professor's been asking me to check out a strange weather pattern coming from the northeast.\n\nThing is, I'm going to need a co-pilot if we're going into uncharted territory.  No way in hell I'm heading out there alone.\n\nWhat do you say, <tough-guy/hotshot>?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.", sourceObjective = "Help Pilot Vic complete the Reconnaissance Flight.", completion = "You saved my life up there, buddy.  Nice flying!", sourceObjectiveStatus = "unverified-source-field" }
quests[12672] = { id = 12672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Stage", description = "I will give you a chance at continued existence.\n\nThere are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet.\n\nGo, insect. Run and do my bidding before I change my mind about letting you live.", sourceObjective = "Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so.", progress = "What a shame that Har'koa didn't send you along sooner. Then again, she and I never did get along.\n\nShe probably held back your help just long enough for this to happen.", completion = "They'll do. Likely I won't even need them.\n\nBut it was fun watching you run around at my command.", sourceObjectiveStatus = "unverified-source-field" }
quests[12673] = { id = 12673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Rolls Downhill", description = "If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a great leader - one who be commandin' respect!\n\nI got a task dat gonna refine your command skills, mon....\n\nSumma my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon.\n\nTake dis scepter and teach 'em how to get da job done. When dey be under your control, make 'em harvest dem crystals!", sourceObjective = "Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals.", progress = "Ya got my underlings whipped into shape, {name}?", completion = "Da crystals be pilin' up like never before!\n\nYou keep up da good work, {name}. I got more tasks for ya real soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12674] = { id = 12674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell Hath a Fury", description = "It is now time for you to punish my three high priests: Mu'funu, Tua-Tua, and Hawinni. You'll find them spread around the altar grounds.\n\nTake this hexxing stick. I've empowered it with my rage and indignation. I'm sure that it will prove potent.\n\nJust use it and proceed to destroy them. The hex will take care of the rest.\n\n<Quetz'lun displays a toothy grin.>\n\nSucceed and I may let you go. Fail and die.", sourceObjective = "Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.", progress = "DO YOU THINK THAT I'M A FOOL?\n\nTHEY'RE NOT DEAD!", completion = "<The terrible spirit before you lets loose a blood-chilling cackle.>\n\nThey had it coming. And I'll give them more of the same again and again and again....", sourceObjectiveStatus = "unverified-source-field" }
quests[12675] = { id = 12675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Thing", description = "There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods' spirit. You're going to need to beseech Har'koa for some of hers.\n\nOnce you've done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you'll be able to get to my prophet without having to worry about them.", sourceObjective = "Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa.", progress = "You've returned, {name}.", completion = "A portion of my spirit?\n\n<The snow leopard goddess pauses a moment to consider.>\n\nThat's quite an expensive gift considering that this is for revenge and I'm already greatly weakened by the actions of my subduers.\n\nStill, I may know a way.", sourceObjectiveStatus = "unverified-source-field" }
quests[12676] = { id = 12676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage", description = "While we're working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru's bidding.\n\nEvery task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind.\n\nWhile you're there, I have another mission for you. Drakuru's Scourgewagons pose a significant threat. We need them destroyed. \n\nMake your way to the wagons and activate these charges. Once they're set, get clear! The explosion will expose you if you're too close.", sourceObjective = "Stefan at Ebon Watch wants you to perform another task for Drakuru.\n\nAdditionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Were you successful in clearing those scourgewagons, {name}?", completion = "Excellent!\n\nYour undercover work has truly paid off, {name}.\n\nNow let's have a look at that scepter....", sourceObjectiveStatus = "unverified-source-field" }
quests[12677] = { id = 12677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazardous Materials", description = "Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's working on something significant.\n\nContinue to do his bidding and perhaps once he's more familiar with you he'll reveal his plans. In the meantime, we need to have a look at these crystals.\n\nWhile you're in Voltarus, try to get some samples of the harvested crystals when no one's looking.\n\nBe alert! Handling those crystals can trigger your disguise to fail.", sourceObjective = "Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Welcome back, {name}.\n\nWere you able to steal any samples of Drakuru's crystals?", completion = "Fascinating!\n\nWe'll look into the properties of these crystals right away.\n\nNow tell me, {name}, what is the latest with this Drakuru fellow?", sourceObjectiveStatus = "unverified-source-field" }
quests[12678] = { id = 12678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Chaos Drives, Let Suffering Hold The Reins", description = "They make their stand now, outside of Death's Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens.\n\nThis will be your first lesson in Scourge warfare: TERROR!\n\nGo to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march.\n\nBut most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.", sourceObjective = "Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.", completion = "Do you feel it, {name}? That sensation is raw power coursing through your body. Such a thing cannot exist for mortals.\n\nThe front lines are now dismantled. The geist will finish the job and prepare the grounds for Razuvious. We turn our attention now to more tactical targets.", sourceObjectiveStatus = "unverified-source-field" }
quests[12679] = { id = 12679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonight We Dine In Havenshire", description = "The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can't allow those cowards to make it to safety and then take up arms against us!\n\nThere is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.", sourceObjective = "Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows.", progress = "The trajectories they are firing at would have most of the arrows land at or near the Havenshire Farm, south of us.", completion = "Well done, {class}! You feed the Scourge war machine with your deeds!\n\nAh yes, your reward - as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[12680] = { id = 12680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Palomino", description = "How fortuitous it is that the Crusade has a stable full of horses a mere stone's throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully <his/hers>!\n\nOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.\n\nRemember, {name}, it's only stealing if you're caught. Watch out for that deranged stable master, Kitrik!", sourceObjective = "Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach.", progress = "You don't want to walk forever, do you?", completion = "Now for the true test. Can you show mastery over an unbound charger and brutally overtake the thing that you desire most?", sourceObjectiveStatus = "unverified-source-field" }
quests[12681] = { id = 12681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagent Agent", description = "That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite.\n\nIt's not my place to say whether the rumors are true or not, but I've a feeling there's something here.\n\nThe rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage's research?", sourceObjective = "Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost.", progress = "Were you able to find any of the twisted talons?", completion = "<Colvin looks admiringly at the talons you've brought back.>\n\nThese will more than suffice. The gorlocs have a saying that the more gnarled the talon, the more power it holds. I'm sure the archmage will get his money's worth from this expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[12683] = { id = 12683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning to Help", description = "There's no more caustic material in all of the basin than bittertide hydra sputum. I've got special containers to collect just such a thing for Archmage Pentarus' studies. Now all I need is a brave, um... collector.\n\nYou look like a hardy, adventurous {class}. How'd you like to make a bit of money and aid Dalaran's cause at the same time?\n\nAll you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.", sourceObjective = "Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra.", progress = "Did you get those samples?", completion = "Wonderful! Here's your payment, as agreed. And, uh, a bit of advice: you might want to enjoy long, hot baths the next few days if that 'burning sensation' persists.", sourceObjectiveStatus = "unverified-source-field" }
quests[12684] = { id = 12684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of a Dead God", description = "Mam'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power.\n\nIf I'm to sacrifice a portion of my spirit, I will need something with which to bolster myself.\n\nMam'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz'lun. Within the crater his blood yet lives.\n\nBring it to me.", sourceObjective = "Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa.", progress = "I wish that there were something that we could do to bring Mam'toth back to life, but there isn't.\n\nWe can honor him and his sacrifice by continuing the fight against the Drakkari.", completion = "Very well. Let us see if this works....", sourceObjectiveStatus = "unverified-source-field" }
quests[12685] = { id = 12685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Reap What You Sow", description = "This is what it has come down to... revenge.\n\n<Har'koa sighs.>\n\nTake this ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.\n\nThe rest will be up to you, {name}. You must slay the prophet in his drained state.", sourceObjective = "Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga.", completion = "<The witch doctor shakes his head in disbelief.>\n\nIt sounds like you barely escaped Quetz'lun's underworld alive.\n\nI'm glad that it's you out there. I don't know if I would have had the courage to deal with that situation!", sourceObjectiveStatus = "unverified-source-field" }
quests[12686] = { id = 12686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zero Tolerance", description = "Ignorance! Dis be intolerable, mon! My entire batch of blight be useless!\n\nDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon!\n\nDis be a good lesson for ya, {name}. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin' you!\n\nTake dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just to da south.\n\nLet dat be an example to all, mon. Don't be failin' Drakuru!", sourceObjective = "Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.", progress = "Has Darmuk paid for his failure, {name}?", completion = "Ya done good, {name}. You be learnin' faster than I had hoped.\n\nGo now, get ya some rest. Soon I be givin' ya an even greater test!", sourceObjectiveStatus = "unverified-source-field" }
quests[12687] = { id = 12687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Realm of Shadows", description = "The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger?\n\nIf you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death's Breach. Issue the Horseman's Call should you succeed.", sourceObjective = "Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger.\n\nShould you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar.", progress = "You must take the deathcharger by force, {class}!", completion = "You have succeeded where most initiates fail, {name}. For that you will be rewarded handsomely.", sourceObjectiveStatus = "unverified-source-field" }
quests[12688] = { id = 12688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering a Disaster", description = "These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won't let me return to the camp.\n\nIf you'll help me fight our way out of here, we can teach these thugs a lesson they'll never forget!", sourceObjective = "Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp.", completion = "Thank you for freeing Helice and seeing to her safe return. We all started to get worried when she didn't return from her crystal hunting trip.", sourceObjectiveStatus = "unverified-source-field" }
quests[12689] = { id = 12689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand of the Oracles", sourceObjective = "Hi! Really glad see you again!\n\nI knew we friends. I knew it! You good friend. Not just for us, but for all Oracles. Thank you for saving us! Thank you, thank you!\n\nI saw you bonk that puppy-man good! Undead thing said he your friend before? I not know that. You done with puppy-men though, yeah? Just Oracle friend now?\n\nStop! No agree without thinking - you sure you not want to be friends with puppy-men anymore?", sourceObjectiveStatus = "unverified-source-field" }
quests[12690] = { id = 12690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Fire", description = "It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls!\n\nDey breached our wall and put a whole army just north of us.\n\nHahaha!\n\nDey be fuel for da fire, mon! We gunna take da chieftiains an' kill da rest! It all be part of my master plan....\n\nYou take dis scepter and go command my abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch 'em up and bring 'em here to me.", sourceObjective = "Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains.\n\nChieftains will appear when enough Skullcrushers have been slain.", progress = "Did ya smash da trolls, {name}?", completion = "We done it, mon!\n\nI got da chieftains all caged up and you led my abominations to victory over their armies.\n\nIt be time ta celebrate, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12691] = { id = 12691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timeworn Coffer", description = "The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole.\n\nPerhaps one of the guardians in the vicinity has this key in its possession.", sourceObjective = "Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook.", progress = "The stone coffer does not budge.", completion = "The huge stone key turns with a deep grunt as the coffer lid opens up to reveal hidden treasure inside.", sourceObjectiveStatus = "unverified-source-field" }
quests[12692] = { id = 12692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Lich Hunter", description = "Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what you done for wolvar and for Zepik. You great hunter and they dumb to think you not.\n\nGo back to hill and talk to Elder Harkek... I make sure he knows you not traitor before any other Frenzyheart.\n\nThank you, Lich Hunter.", sourceObjective = "Return to Frenzyheart Hill and speak to Elder Harkek.", completion = "It good to see you again. I knew you not a traitor, I glad Zepik prove me right.\n\nI hear you Lich Hunter now - that pretty good! You make Harkek proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[12695] = { id = 12695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Friendly Dryskin", description = "Yay! Soo-say probably worrying about us! Maybe you go back to town and tell him everything okay? Yeah, go tell Soo-say.\n\nI going grab shiny ball thing from dead lich guy - I meet you there! Go go! I meet you there!", sourceObjective = "Return to Rainspeaker Canopy and speak to High-Oracle Soo-say.", completion = "Good to see you again! We worried when you not come back right away.\n\nJaloot beat you back - lot of energy in Jaloot, he pretty fast. He told me how you save him from lich thing. Moodle told me how you save mosswalkers too. You really nice.\n\nI hope you stay with us for while. Always something need doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[12696] = { id = 12696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northeast.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.", sourceObjective = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.", completion = "The professor sent you my way?  All right.", sourceObjectiveStatus = "unverified-source-field" }
quests[12697] = { id = 12697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gothik the Harvester", description = "CHAOS, {name}! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light's Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast.\n\nLet's stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.", sourceObjective = "Speak with Gothik the Harvester at Death's Breach.", completion = "You have fought hard to invade the realm of the harvester... Wait.\n\n<Gothik looks at his notes.>\n\nMy apologies, {race}. Old habits die hard.\n\nValanar sent you, then? I trust you are somewhat competent.\n\nI do have a gift for the Scarlet dogs. One that is sure to speed up their work in the mines.", sourceObjectiveStatus = "unverified-source-field" }
quests[12698] = { id = 12698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift That Keeps On Giving", description = "I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I'm all out of souls.\n\nThis device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!", sourceObjective = "Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.", progress = "One small note: miners don't always become ghouls. Sometimes they turn into enraged spirits, hell-bent on killing you.", completion = "They now know that the mines are no longer safe. They will double their efforts in retreating, leaving their backs open to us!", sourceObjectiveStatus = "unverified-source-field" }
quests[12699] = { id = 12699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Embarrassing Incident", description = "There's one little problem we have to solve before we head out.  You see, I can't seem to find the keys to my flying machine.\n\nI've looked pretty much everywhere for them... maybe you can give me a hand.  Only place I haven't looked yet is inside the lake.\n\nI'll even give you my very own air tank.  It's almost empty, but it's got a couple of hits left.", sourceObjective = "Look for Vic's Keys inside the lake at River's Heart.", progress = "You find anything yet, {name}?", completion = "Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[12700] = { id = 12700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Attack Of Opportunity", description = "Only the Scarlet forces at New Avalon and Light's Point challenge us! The time to attack the Scarlet fleet at Light's Point has come.\n\nThe diversion at the mine has caused chaos amidst their ranks. They are frantically working to clear the area and return to their ships.\n\nThe time is ripe! Prince Valanar is seizing this opportunity to finish off the Scarlet fleet. Report to him at once!", sourceObjective = "Speak with Prince Valanar at Death's Breach.", completion = "You have served us well, {class}. Few of your brethren have survived our initial attack upon the Scarlet interlopers. You remain as one of the strongest.\n\n\n\nEast of us, past the Havenshire Mine, is the coast - called Light's Point by the Scarlet Crusade. A thousand soldiers stand between us and their ships. Insurmountable? Hardly the point...", sourceObjectiveStatus = "unverified-source-field" }
quests[12701] = { id = 12701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massacre At Light's Point", description = "In their haste the Crusade will make one fatal error: forgetting to check the mine cars.\n\nYou are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines.\n\nOnce aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL!\n\nCall the Scourge gryphon from the cannon when you are ready to return.", sourceObjective = "Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders.", progress = "Death knights know no fear!", completion = "The entire Scarlet fleet wiped out in a matter of minutes! I will receive a commendation from the Lich King for this! All that remains of the Scarlet Crusade now are the denizens of New Avalon.\n\nI'll set the fire starters and necromancers upon Havenshire immediately. You will carry my report to the Highlord!", sourceObjectiveStatus = "unverified-source-field" }
quests[12702] = { id = 12702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Party!", description = "I bet you not guess what happen again.\n\nNope, not Goregek or chickens.\n\nOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly.\n\nLet me know if you need help from any of the hunters... they around here somewhere.", sourceObjective = "Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill.", progress = "Chickens not get far usually... if wasps not eat them, maybe we just let them stay on field next time.", completion = "You good at this.\n\nMaybe someday we just dump Goregek in river so you not have to do this no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12703] = { id = 12703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kartak's Rampage", description = "You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even.\n\nBig battle at Kartak's Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue.\n\nKartak take your body if you worthy... with Kartak's powers, you slaughter more big-tongues than even best dreams.\n\nGo kill lots, hunter!", sourceObjective = "Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak's shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak's Hold.", progress = "So many big-tongues to kill! So fun, eh?", completion = "Ritual went so easy for you!\n\nYou come back later for more killing someday, okay?", sourceObjectiveStatus = "unverified-source-field" }
quests[12704] = { id = 12704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appeasing the Great Rain Stone", description = "Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer!\n\nYou good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.", sourceObjective = "High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures.\n\nBe sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions.", progress = "Never enough shinies... Great Rain Stone good to us, we need be good to Great Rain Stone.", completion = "So many good shinies! You good at this.\n\nCome back for more again later, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[12705] = { id = 12705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Titans", description = "Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too.\n\nYou been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with.\n\nPuppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help.\n\nDon't be scared if Soo-holu take your body... he very powerful, so he keep you safe.", sourceObjective = "Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu's shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone.", progress = "Thank you for help dryskin. You very good to us.", completion = "Soo-holu strong, huh? I very glad he accept you to share his body for fight.\n\nHe more trusting of people he met before, so maybe come back another time to help more, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[12706] = { id = 12706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory At Death's Breach!", description = "<Prince Valanar hands you a sealed scroll.>\n\nThis is the full report of our victory at Death's Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, {name}.\n\nGo now!", sourceObjective = "Deliver Prince Valanar's Report to Highlord Darion Mograine in Acherus: The Ebon Hold.", progress = "I was certain you wouldn't make it back here in one piece, {class}. Perhaps there is more to you than I first surmised.", completion = "<Highlord Mograine reads over the report.>\n\nThe ENTIRE Scarlet fleet?\n\n<Highlord Mograine nods.>\n\nSuch power, {name}... I have not seen such a display of domination in years... Since my father wielded...\n\n\n\nIt's not important...\n\nYes, your commendation, lest I forget.", sourceObjectiveStatus = "unverified-source-field" }
quests[12707] = { id = 12707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wooly Justice", description = "Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth are enraged and cry out for justice!\n\nFollow the avenue northeast up the steps to the next tier of Zul'Drak. On your right you will find what's left of the Altar of Mam'toth.\n\nWhen you get there, flash this Medallion of Mam'toth in front of the eyes of one of the enraged mammoths. It'll calm down for a little while, letting you hop on its back.\n\nRide it around, trampling all of the Mam'toth disciples that you can find!", sourceObjective = "Scalper Ahunae at Zim'Torga wants you to use the Medallion of Mam'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam'toth Disciples to death.", progress = "What? You done already?\n\nDid you enact wooly justice upon those sorry ice trolls?", completion = "Score one for the victims, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12708] = { id = 12708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Tiki Warriors", description = "I know that you're headed up to the Zol'Maz Stronghold to the northeast, {class}. While you're there, I need you to deal with the warlord's special guardians.\n\nThe enchanted tiki warriors, as they're called, represent a very real threat. If the Drakkari were to mass produce them, we'd quickly be overrun.\n\nLet's you and I demonstrate that they're not worth the effort to create, shall we?", sourceObjective = "Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors.", completion = "That should make them think twice about making more of those things. I shudder to think what it would be like to have to fight an army of those things.\n\n<The element-tamer is thoughtful for a moment.>\n\nI guess it would be just like fighting the endless waves of the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12709] = { id = 12709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexed Caches", description = "Pardon me, {name}. I'm given to understand that you might be heading northeast up to the Zol'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.\n\nAs I have come to know, the Drakkari warlord is extremely paranoid. He's had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?\n\nIf you could find the time to acquire some of those goods, I would be most appreciative.", sourceObjective = "Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches.", progress = "Perhaps you carry the caches within your pack even as we speak?", completion = "Just look at all of that!\n\nSee here, {name}. This piece you recovered vividly illustrates that the Drakkari became aware of the weakening of the land that the Scourge caused by their presence.\n\nThe warlord felt compelled to take the opportunity this presented. He pushed the prophets to kill their gods in an effort to control the power and fight back against the Lich King's forces.\n\nEither way they were doomed. They inadvertently chose to be the instrument of their own destruction!", sourceObjectiveStatus = "unverified-source-field" }
quests[12710] = { id = 12710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disclosure", description = "Ya doin' well, {name}.\n\nYou be provin' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing....\n\nDa time has come for me to reveal my master plan to ya, mon.\n\nNow you be seein' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak.\n\nTake dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.", sourceObjective = "Drakuru in Voltarus wants you to take the teleporter to his upper chamber.", progress = "Have ya gone ta witness my creations, {name}?", completion = "So, there ya have it, mon.\n\nWe be makin' da ultimate scourge army ta serve da Lich King. He gunna be most pleased!\n\nYou keep da scepter, {name}. You gunna be needin' it ta command my army in battle....\n\nSoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12711] = { id = 12711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Mail", sourceObjective = "Atop the mailbox are several illegible letters and scrolls. Useless...\n\nPerhaps you should check inside?", sourceObjectiveStatus = "unverified-source-field" }
quests[12712] = { id = 12712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key of Warlord Zol'Maz", description = "{name}, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.\n\nThe Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.\n\nThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.", sourceObjective = "Har'koa at Zim'Torga has asked you to acquire the Key of Warlord Zol'Maz.", progress = "I cannot stress how important it is that you acquire the warlord's key no matter the cost.", completion = "It might have been better if I hadn't asked you to bring it back here instead of heading directly to Gundrak.\n\nHowever, I think that it's best that you hear what else I have to say first.", sourceObjectiveStatus = "unverified-source-field" }
quests[12713] = { id = 12713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal", description = "The time has come to end this charade, {name}.\n\nAs valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed.\n\nWe've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him.\n\nFight well.", sourceObjective = "Stefan in Ebon Watch wants you to defeat Drakuru.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Have you faced Drakuru in battle, {name}?", completion = "So, it is done.\n\nWe still have much to do, but our work here will be much more manageable thanks to your efforts.\n\nPlease accept this as a token of our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[12714] = { id = 12714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will Of The Lich King", description = "It is the will of the Lich King that drives us onward, {name}. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts...\n\nCan you hear him now? Perhaps it is too early for you.\n\n<Mograine closes his eyes and nods to an unseen host.>\n\nYes, my lord. It will be done.\n\n{name}, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!", sourceObjective = "Return to Death's Breach and report to Prince Valanar.", completion = "Havenshire is ours! A thousand corpses litter the ground, patiently awaiting rebirth. We strike now at our enemy with the awakened strength of the Scourge!\n\nThe ghouls have already begun their assault upon New Avalon. Our forces have moved in behind them and taken the Crypt of Remembrance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12715] = { id = 12715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crypt of Remembrance", description = "The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade's front lines down while we labor to fortify our new forward base, the Crypt of Remembrance.\n\nVenture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth.\n\nHe will be expecting you.\n\nPrepare yourself, {name}, for you are about to witness the next stage of Scourge warfare: DOMINATION!\n\nRide now, death knight!", sourceObjective = "Report to Prince Keleseth at the Crypt of Remembrance.", completion = "Hail, {class}. I am the blood lord, Keleseth, ruler of the southeastern reaches of Northrend. The Lich King has sought to utilize my talents in ending this mortal affront to the Scourge. As with all things the Lich King asks of me, I am happy to oblige. Of course, a sea of endless souls to sate my thirst certainly sweetened the deal, don't you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[12716] = { id = 12716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plaguebringer's Request", description = "Look at this pumpkin patch! Notice anything missing? Of course you don't, because you're a moron! Your brain was probably the first thing to die.\n\n<Noth sighs.>\n\nI have been commanded to put together a plague cauldron. You will help me.\n\nDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?", sourceObjective = "Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.", progress = "Have you gathered the materials I requested?", completion = "Perfect! Now give me a moment to get things set up.", sourceObjectiveStatus = "unverified-source-field" }
quests[12717] = { id = 12717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth's Special Brew", description = "The cauldron is ready to begin spewing its foul corruption across the land!\n\nNow, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds.\n\nTake these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.", sourceObjective = "Place the Pile of Crusader Skulls inside the Plague Cauldron.", progress = "The plague cauldron stands idle.", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds some vials of dark liquid float to the top.", sourceObjectiveStatus = "unverified-source-field" }
quests[12718] = { id = 12718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Skulls For Brew", progress = "The plague cauldron bubbles and churns its toxic brew, spewing a thick gas all around.\n\nDo you have more Crusader skulls to place inside?", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds, the plague cauldron grants you the dark and frothy splendor of Noth's Special Brew." }
quests[12719] = { id = 12719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere To Run And Nowhere To Hide", description = "Nothing less than total annihilation will suffice, {name}. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge's grasp!\n\nMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.", sourceObjective = "Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry.", progress = "There is nowhere to run!", completion = "The registry will tell us many things about the Scarlet insects.\n\n<Keleseth flips through the pages of the registry.>\n\nDeath rates, births, but most importantly, movement.\n\nLook here, {name}, they have already sent three vessels abroad. Let me see here... Where are they headed?\n\n\n\nWHAT? This is impossible. They sail to Northrend!\n\nBeside the coordinates are the words: \"Crimson Dawn.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[12720] = { id = 12720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How To Win Friends And Influence Enemies", description = "In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand.\n\n<Keleseth pulls something out of an ornately jeweled box.>\n\nThese are my \"persuaders.\" Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this \"Crimson Dawn.\"", sourceObjective = "Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the \"Crimson Dawn.\"\n\nRemove Keleseth's Persuaders from the Ornately Jeweled Box and use them to \"persuade\" the Scarlet Crusade into talking.", progress = "Use the persuaders on Scarlet Crusaders. One of them will eventually... crack.", completion = "An awakening? What nonsense do you speak, boy! What kind of fool would deliver their people into the very heart of the frozen wastes? Perhaps, though, this courier holds the answer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12721] = { id = 12721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampage", description = "{name}, there is no time left. You must take the key and use it to unlock Akali.\n\nHe is being held in the courtyard in front of Gundrak, the capital of Zul'Drak. Akali's chains are secured by four anchor points. You must unlock each of them to set the rhino god free.\n\nGundrak is teeming with ice trolls. However, I believe that if you're careful, you should be able to slip in without too much danger.\n\nOnce you're done, please inform the witch doctor.", sourceObjective = "Har'koa at Zim'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim'Torga.", progress = "What happened?", completion = "No!\n\nAnother god destroyed, its power stolen. And now the prophet of Akali has threatened us directly.\n\nWhen he comes, he will come for Har'koa. We cannot allow him to take her power too.\n\nWe must consult the gods once more, {name}. They will tell us what must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[12722] = { id = 12722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lambs To The Slaughter", description = "Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade!\n\nI must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle!\n\nWe shan't deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.", sourceObjective = "Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.", progress = "Like lambs to the slaughter...", completion = "You are quite effective with that blade, {name}. Perhaps, Lich King permitting, you would be interested in becoming one of my minions? Stratholme is looking for a new mayor.", sourceObjectiveStatus = "unverified-source-field" }
quests[12723] = { id = 12723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Scarlet Lines", description = "I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the courier. They have set up a base of operations at the Scarlet Tavern, located at the southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to Orbaz Bloodbane. He will update you on their situation.", sourceObjective = "Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", completion = "Looks like we'll let anyone into the dark order these days. When I was given the gift, things were different. Much different!\n\nAs to this courier...", sourceObjectiveStatus = "unverified-source-field" }
quests[12724] = { id = 12724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Of The Righteous Crusader", description = "We haven't got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either.\n\n<Orbaz points to the Scarlet corpses strewn across the floor.>\n\nI did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule.\n\nThe hold is the largest building in New Avalon - northeast of here.", sourceObjective = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.", progress = "Tear the hold apart! The schedule is there!", completion = "<Orbaz flips through the schedule.>\n\nThese worthless cretins have been busy! Northern patrol routes, southern patrol routes, western patrol routes, eastern patrol routes, but nothing about their couriers' routes. Wait a minute. What's this? It looks like a western patrol route, coming out of Western Plaguelands? This patrol will path through here today! I'm going to need time to plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[12725] = { id = 12725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers In Death", description = "Breaking through the Scarlet lines was no easy task. We suffered many casualties during the assault and lost one of our best death knights, Koltira Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't search for him.\n\nI last saw him being bound in irons and dragged away to the Scarlet Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!", sourceObjective = "Search for Koltira Deathweaver in the Scarlet Hold.", completion = "You were foolish in coming after me. I failed. I should have been left for dead - now two of us might be killed.\n\n<Koltira shakes his head.>\n\nWe are death knights of the Scourge. This flies in the face of the dark brotherhood's covenants.\n\nThassarian, you blasted fool!", sourceObjectiveStatus = "unverified-source-field" }
quests[12726] = { id = 12726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Wind and Water", description = "Listen to storm, yes?  The Stormwright's Shelf echoes with ancient song.... the Song of Wind and Water.\n\nThe great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon's song.\n\nHelp him feed on wind and water so tempest can continue.", sourceObjective = "Soo-nee wants you to use the Tempest Drums at the Stormwright's Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits.", completion = "I thank you, {name}.  The great tempest will look upon us favorably thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12727] = { id = 12727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Breakout", description = "The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I'm too badly injured to be of much use, but I'll do what little I can to help.\n\nSlay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul.\n\nOne more thing, {name}. If you do manage to survive and make it back to Thassarian, tell him that they're executing prisoners at the chapel. Perhaps he'll send you there to play the hero once more.", sourceObjective = "Slay High Inquisitor Valroth and take Valroth's Head to Thassarian at the Scarlet Tavern in New Avalon.", progress = "What of Koltira?", completion = "I'll feed this monster's head to the ghouls!\n\n<Thassarian tosses the head into the back room.>\n\nDid Koltira make it out?\n\n<Thassarian pauses.>\n\nI'm certain he did. Those walls can't hold him.\n\nTime for some payback.", sourceObjectiveStatus = "unverified-source-field" }
quests[12728] = { id = 12728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Winterfin Cavern", description = "I need to compile my notes and prepare a presentation for my colleagues in Dalaran.\n\nWhile I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern.\n\nReturn to me at once when you have the data. My documentation will be incomplete without it.", sourceObjective = "Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.", progress = "Have you collected the data from Winterfin Caverns yet, {name}?", completion = "Excellent, this completes my report.\n\nI'll be sure to mention your kindness to the council, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12729] = { id = 12729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gods Have Spoken", description = "The gods have spoken and we must heed their wisdom.\n\nTravel north to Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Travel east to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty essence.\n\nDeliver both to Har'koa and she will combine them into that which will compel late Akali's prophet to appear.", sourceObjective = "Deliver the Unblemished Heart of the Guardian and the Gusty Essence of the Warden to Har'koa at Zim'Torga.", progress = "Do you have that which is required, {name}?", completion = "Your bravery seems boundless, {name}.\n\nPlease hand me the heart and the essence, and I will fashion them into that which will compel the prophet to appear before you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12730] = { id = 12730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convocation at Zol'Heb", description = "You must take this instrument of convocation - of summoning - to Zol'Heb just south of Gundrak.\n\nTherein you will find a circle of power. Use the convocation to force the prophet of Akali to appear.\n\nMy heart goes out to you, {name}. We have been through much together, and you have done all that you can to not only save my life, but those of the other gods the Drakkari have destroyed.\n\nBut I fear this time we may not see each other again until the afterlife.", sourceObjective = "Har'koa at Zim'Torga has asked you to slay the Prophet of Akali.", progress = "I can only offer you the warmth of my words and the encouragement that comes with them.\n\nTake what time you need to steel and prepare yourself, but I implore you not to take too long or the prophet will surely descend upon us.", completion = "You did it! {name}, you are the champion of Zul'Drak!\n\nWe will never be able to repay the debt that we owe to you, but the Zandalari have given into my trust a number of objects they believe you might have an interest in.\n\nPlease, I want you to have a token of our appreciation, but hurry. I sense another issue of urgency!", sourceObjectiveStatus = "unverified-source-field" }
quests[12732] = { id = 12732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heartblood's Strength", description = "One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon.\n\nRejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial.\n\nThen go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood.\n\nYou combine heartblood and water, bring to Rejek. Rejek drink, make strong.", sourceObjective = "Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill.", progress = "You bring Rejek gift?", completion = "Rejek thanks you. Rejek drink, grow strong, always remember mighty {name}'s gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[12733] = { id = 12733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Challenge", description = "Born of the Lich King's victory over Illidan Stormrage in the heart of the frozen wastes, Death's Challenge is a rite of passage that all death knights must undergo.\n\nSeek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges!\n\nGo now, {name}! Victory for the Scourge! Glory to the Lich King!", sourceObjective = "Olrun the Battlecaller has ordered you to win 5 duels against other death knights.\n\nYou may choose to battle death knight initiates or players.", progress = "Have you completed Death's Challenge?", completion = "To the victor goes the glory, {class}! Well done! The Lich King looks favorably upon you on this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[12734] = { id = 12734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejek: First Blood", description = "Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek?\n\nTake blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.", sourceObjective = "Blood Rejek's Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.", progress = "You blood Rejek's blade?", completion = "Rejek sees the stains of the blood of his enemies on the blade. Now Rejek has a mighty weapon for the mighty warrior he will be!", sourceObjectiveStatus = "unverified-source-field" }
quests[12735] = { id = 12735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cleansing Song", description = "Earth in Sholazar is pure.  The pillars have protected the land for centuries.\n\nWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.\n\nYou take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.", sourceObjective = "Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there.", progress = "You play cleansing song yet, {name}?", completion = "Waters... cleansed.  Yes.  All is well.\n\nYou understand our way, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12736] = { id = 12736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Reflection", description = "Of course you not as smart as gorloc!  You just simple {race}.\n\nYou not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart!\n\nI teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc's but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!", sourceObjective = "Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar.", progress = "You feel smart yet, {race}?", completion = "You see?  I can tell you smarter already.  And if not smarter... then... happier!", sourceObjectiveStatus = "unverified-source-field" }
quests[12737] = { id = 12737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Fecundity", description = "The storm is a destructive force.  Storm burns trees.  Storm floods houses.\n\nBut storm can also be life force if you know right song.  In Stormwright Shelf, above Maker's Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song.\n\nYou take this horn and play song for them.", sourceObjective = "Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright's Shelf, northwest of the Maker's Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt.", completion = "You learn fast, {name}.  You learn that song well.  Maybe next time I teach you different song.", sourceObjectiveStatus = "unverified-source-field" }
quests[12738] = { id = 12738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry For Vengeance!", description = "The cry for vengeance must be heard, {name}. Commander Plaguefist and a company of death knights are on their way to raze the Chapel of the Crimson Flame. If there are any death knights imprisoned at the chapel, Plaguefist will get them out.\n\nYou can still catch up to them if you hurry. The chapel is due west of here.", sourceObjective = "Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame.", completion = "They're only flesh and bone - no match for the Scourge.\n\nWe didn't find any of our brothers, but we did stumble upon something special.", sourceObjectiveStatus = "unverified-source-field" }
quests[12739] = { id = 12739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty tauren in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12740] = { id = 12740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parachutes for the Argent Crusade", description = "Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go.\n\n{class}, you have to get these parachutes out to them! At least then they'll have a fighting chance to survive.", sourceObjective = "Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.", progress = "If you're back here talking to me why do I still see my people falling to their deaths?", completion = "You're a good man, {name}. We're fortunate that you happened to stop by.\n\nStick around a while. I'm sure that we have much that a capable {class} such as yourself can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[12741] = { id = 12741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of the Tempest", description = "Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it!\n\nFar to northwest, there is large, flat area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by flying like bird.\n\nOn this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at shelf's western side. Rejek will await your return with ultimate power.", sourceObjective = "Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest.", progress = "You bring Rejek true power of elements?", completion = "Now Rejek show cowardly big-tongues how to really use elements!", sourceObjectiveStatus = "unverified-source-field" }
quests[12742] = { id = 12742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty human in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12743] = { id = 12743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty night elf in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Yazmina Oakenthorn, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12744] = { id = 12744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty dwarf in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Donovan Pulfrost, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12745] = { id = 12745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty gnome in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Goby Blastenheimer, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12746] = { id = 12746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty draenei in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Valok the Righteous, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12747] = { id = 12747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty blood elf in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Lady Eonys, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12748] = { id = 12748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty orc in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Kug Ironjaw, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12749] = { id = 12749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty troll in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Iggy Darktusk, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12750] = { id = 12750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty Forsaken in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Antoine Brack, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12751] = { id = 12751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sort Of Homecoming", description = "Return to Thassarian at the Scarlet Tavern and let him know that Koltira's cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours.\n\nYou're one cold-blooded monster, {name}. I salute you, <brother/sister>.", sourceObjective = "Return to Thassarian at the Scarlet Tavern in New Avalon with news of your victory.", completion = "Another Scourge victory! These Scarlet dogs have nowhere left to run and hide. It's only a matter of time now...", sourceObjectiveStatus = "unverified-source-field" }
quests[12752] = { id = 12752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "Greetings, brother.  You may have come on behalf of the Argent Dawn, but that is not why you are here -- you are here to help your people earn the respect we so justly deserve.  As any forsaken will agree, the end justifies the means, and our research into the zombie plague's cure is that proverb in practice...", sourceObjectiveStatus = "unverified-source-field" }
quests[12753] = { id = 12753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "Brother {race}, I am proud to stand with you during our days of need.  Bless you, and may the alliance between {race} and human last a thousand years.", sourceObjectiveStatus = "unverified-source-field" }
quests[12754] = { id = 12754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambush At The Overlook", description = "While you were out burning churches and murdering vermin, I've been busy formulating a plan.\n\nThe Scarlet courier is scheduled to pass by the Scarlet Overlook within the hour. The roads by the overlook are wide open and swarming with Crusaders. Use this makeshift cover to hide at the overlook and wait for the Scarlet Courier to pass. When he's close enough, strike with all your fury! Cut him down and take his belongings - including his clothes!\n\nThe overlook is 200 paces east of here.", sourceObjective = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to kill the Scarlet Courier and retrieve the Scarlet Courier's Belongings and the Scarlet Courier's Message.", progress = "You're going to miss the courier and then I'm going to be forced to kill you. By forced I mean I will take great pleasure in ending your life.\n\nHURRY UP!", completion = "<Orbaz reads the message.>\n\nThe armies of Hearthglen and Tirisfal will be marching into a massacre.\n\n<Orbaz smiles.>\n\nNow for the second part of the plan. You're going to deliver this message right into the hands of High General Abbendis. That's what the clothes are for...", sourceObjectiveStatus = "unverified-source-field" }
quests[12755] = { id = 12755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meeting With Fate", description = "This message must reach Abbendis. We do not want to draw their suspicion. They must continue under the assumption that everything is going as they planned.\n\nYou will don the Scarlet courier's clothes and with the help of some dark magic, take on the form of the courier.\n\nAbbendis is at King's Harbor, southeast of the Scarlet Overlook. Drop off the message and get as much information out of her as you can. She will tell us what we need to know about the \"Crimson Dawn.\"", sourceObjective = "Orbaz Bloodbane has commanded you to deliver the Scarlet Courier's Message to High General Abbendis at King's Harbor.", progress = "Where have you been? You are two hours late. We were about to send a courier out to the High Commander.", completion = "<High General Abbendis reads the message.>\n\nDamn it! The armies of Hearthglen and Tirisfal must not reach New Avalon! The Scourge will slaughter them all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12756] = { id = 12756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Onslaught Emerges", description = "Listen well, courier. The Scarlet lands are lost. New Avalon and Havenshire are overrun by Scourge. The specter of death looms overhead and threatens to overtake us at any moment.\n\nReturn to Galvar with this message:\n\n\"Turn your armies around and prepare your ships for travel to the frozen wastes. When next we meet it will be in Northrend.\"\n\nGive this to Galvar.\n\n<Abbendis hands you a journal.>\n\nIt will explain everything.\n\nThe Scarlet Crusade is no more. Long live the Scarlet Onslaught!", sourceObjective = "Deliver The Path of Redemption to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", progress = "<Orbaz laughs.>\n\nWhat is this? Some child's coloring book?", completion = "<Orbaz flips through the journal.>\n\nWhat rubbish! This is the \"Crimson Dawn?\"\n\nThey sail to their deaths! Let us turn our focus to the encroaching armies.", sourceObjectiveStatus = "unverified-source-field" }
quests[12757] = { id = 12757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Armies Approach...", description = "We must prepare for the encroaching armies, {name}. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.\n\nGive Highlord Mograine Abbendis' journal as well. Perhaps he'll find it useful.", sourceObjective = "Deliver The Path of Redemption to Highlord Darion Mograine at Acherus: The Ebon Hold.", progress = "You did what?", completion = "You have become an instrument of doom, {class}! We will ravage these approaching armies and raise the dead as our own!", sourceObjectiveStatus = "unverified-source-field" }
quests[12758] = { id = 12758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Headgear", description = "Rejek hears tales of giant metal men on faraway Stormwright's Shelf. Far to northwest, outside basin's lip, you will find it.\n\nImagine Rejek using heads of giant metal men as helmet. Make Rejek unstoppable! Make Rejek mighty!\n\nYou get for Rejek, but metal head might not come off metal body easy. Maybe steal bombs from little green men and their friends at Swindlegrin's Dig near Suntouched Pillar? Use bombs to get head off metal body, then bring to Rejek.", sourceObjective = "Get Venture Co. Explosives from any of the Venture Company units at Swindlegrin's Dig and use them to obtain a Stormwatcher's Head. Bring the Stomwatcher's Head to Rejek at Frenzyheart Hill.", progress = "You bring Rejek's new helmet?", completion = "Rejek sees you were successful! Now Rejek try on new war helmet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12759] = { id = 12759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of War", description = "Zepik tell me that you maybe the best gorloc hunter he met... other than Zepik. Still big battle to southwest - you go help.\n\nZepik keeps some of biggest, baddest traps in his stash at Kartak's Hold... told Vekgar to use them for battle, so you use them too. Go pick out any traps you want and kill lots of big-tongues.\n\nLots and lots!", sourceObjective = "Retrieve some of Zepik's traps from his stash in Kartak's Hold. Using the traps, slaughter 50 of the nearby Sparktouched Gorlocs, and then return to Shaman Jakjek in Kartak's Hold.", progress = "Kind of messy! But still so fun.", completion = "You almost as good with those traps as Zepik!", sourceObjectiveStatus = "unverified-source-field" }
quests[12760] = { id = 12760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Strength of the Frenzyheart", description = "Battle still going at Kartak hold... I think it time for you to learn big secret of Frenzyheart.\n\nWe have berries we keep from other lands we came from... they not so special on their own, but mix them with drunk drinks and they make Frenzyheart super strong. You a Frenzyheart now... it time you get to be strong too.\n\nI give some drink, then you be super strong and you go smash all the spark big-tongues.", sourceObjective = "Using the secret Frenzyheart drink, slaughter 30 of the Sparktouched Gorlocs around Kartak's Hold.", completion = "You a fierce fighter... come back for more battle soon. Never enough good battle!", sourceObjectiveStatus = "unverified-source-field" }
quests[12761] = { id = 12761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery of the Crystals", description = "Sparktouched are still being attacked by puppy-men... we think they maybe not stop if we not make them stop. We have secret weapon though... we sent it out to Soo-met so he can use to protect all Oracles.\n\nSecret weapon is from Great Ones themselves... extra shiny crystals found inside sacred Great One temples. Be very careful... no break them.\n\nCrystals are in chest near shrine at Sparktouched Haven, in far southwest. You go use crystals to help Soo-met beat the puppy-men.", sourceObjective = "Retrieve the crystal defenses at Sparktouched Haven and use them to kill 50 of the nearby Frenzyheart wolvar. When these tasks are complete, return to Lightningcaller Soo-met in Sparktouched Haven.", progress = "Very powerful. Puppy-men not know about power of Great Ones. Dumb puppy-men.", completion = "Thank you, dryskin.\n\nI hold onto these crystals here to keep us safe. Maybe you come back soon and help us more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12762] = { id = 12762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Great Ones", description = "We need to do something to stop puppy-men attacking Sparktouched Haven. Jaloot brought me very special crystal that he found in River's Heart... we seen only one like it before.\n\nThe crystal not have power now, but the opened up lifeblood pillar should have energy to recharge it if you just bring it close. Once the crystal is charged, go to Sparktouched Haven in far southwest and let the crystal's energy make you big and strong.\n\nThen it time to kick some puppy-men butt.", sourceObjective = "Charge the Dormant Polished Crystal at the exposed Lifeblood Pillar. Travel to Sparktouched Haven and use the power the crystal bestows to slaughter 30 of the nearby Frenzyheart wolvar, and then speak to Lightningcaller Soo-met in Sparktouched Haven.", progress = "Good to have you here to help us. Long fight.", completion = "So much energy in you... you full of the power of the Great Ones!\n\n I not lie, I little bit jealous.", sourceObjectiveStatus = "unverified-source-field" }
quests[12763] = { id = 12763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shifting Priorities", description = "As pressing as our needs are here, there's news from the lands to the north that cannot be ignored.\n\nI've just received a message from the Argent Crusade. It seems that scourge forces are gathering there and are threatening to overrun Zul'drak.\n\nNeedless to say, {name}, if that were to happen our struggle here would be meaningless. You must go there and aid the Crusaders in beating back the Lich King's armies.\n\nSpeak to Makki when you are ready to travel.", sourceObjective = "Scout Vor'takh wants you to travel to Zul'Drak and report to Sergeant Riannah at Light's Breach.\n\nMakki Wintergale in Camp Oneqwah will provide you transportation.", completion = "The Light shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[12766] = { id = 12766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nShe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", sourceObjective = "Speak with Lauriel Trueblade at Wyrmrest Temple.", completion = "You must be {name}. I was told you'd be coming.\n\nI have something that I think you're uniquely qualified to take care of and by doing it, you'll be ingratiating yourself with the dragons here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12767] = { id = 12767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nHe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", sourceObjective = "Speak with Golluck Rockfist at Wyrmrest Temple.", completion = "You must be {name}. I was told you'd be coming.\n\n\n\nI have something that I want you to take care of. If you do, you'll prove yourself to the dragons here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12768] = { id = 12768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", sourceObjective = "Speak with Tariolstrasz at Wyrmrest Temple.", completion = "Back so soon, {name}?\n\nCeristrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[12769] = { id = 12769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", sourceObjective = "Speak with Tariolstrasz at Wyrmrest Temple.", completion = "Back so soon, {name}?\n\nVargastrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[12770] = { id = 12770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reallocating Resources", description = "Listen up, {class}!\n\nYour days here are numbered. As much as we need capable {class}s in our ranks, there's trouble up north that makes our problems look like a mid-summer Stormwind parade.\n\nTurns out the Scourge are concentrating their efforts - making a big push to take over Zul'Drak. If that happens, we may as well pack it in.\n\nYou're free to finish any business here, but then it's off to Light's Breach with you. Speak to Samuel if you need transportation.\n\nDismissed.", sourceObjective = "Gryan Stoutmantle wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.\n\nYou may speak to Samuel Clearbook for transportation to Light's Breach.", completion = "The Light shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[12771] = { id = 12771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  Magni Bronzebeard is eager to take the fight to Northrend, and this will bring him closer to his goal.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to King Magni Bronzebeard in Ironforge.", progress = "Hello, {name}.  A stouter {race} I never did see!  The trials of Outland have made you tough, brother.  You do your race proud!", completion = "By my beard!  This holds a power to rival a fleet of our flying machines!  I'll give it to my war priests and we'll devise a plan to send those vile necropolises scurrying back to Northrend... and we'll be right behind them!\n\nOh, Muradin my brother, you must live!  By the honor of the Bronzebeards, I will find you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12772] = { id = 12772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "{name}, honorable {race}, welcome.  May the Light shine upon you, and may your ancient wisdom ward our land in its time of need.", sourceObjectiveStatus = "unverified-source-field" }
quests[12773] = { id = 12773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to Tyrande Whisperwind in Darnassus.", progress = "{name}, my son.  Once again we are pulled into a conflict that may sunder all we know.  It is good to have a {class} of your talents lend his strength to this world tree's defense.", completion = "What is this?  What a boon!  They have captured such Light into this artifact, it shines nigh bright as the moon!  Our priests will channel this power against our foes, and the Lich King's invasion will surely fail.  Thank you, {name}.  Our world tree will be safe.\n\nWhat's more, we have sensed that perhaps another world tree grows far to the north, nestled hidden near the Lich King's own domain.  Perhaps someday... we will shepherd both trees and herald a new era of peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[12774] = { id = 12774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I'm sure he will welcome this tool.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to King Varian Wrynn in Stormwind.", progress = "{name}, it's good to see you.  Your strength and skills are a boon during this time of tribulations.", completion = "So, the holy folk in Shattrath created what they promised!  In hindsight, diverting so many priests and paladins there, instead of sending them against the Scourge, was the right move.  With this holy weapon,  we can beat back that damned Lich King and his minions!\n\nI commend you, Lord {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12775] = { id = 12775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "Brother, we are called again to fight against the Scourge.  It is good you are here; with your strength, and the power of the Light, we may yet prevail.", sourceObjectiveStatus = "unverified-source-field" }
quests[12776] = { id = 12776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exodar", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to the Exodar.  Deliver it to Prophet Velen in the Vault of Lights so that he may use its powers against the unholy forces from the North.", sourceObjective = "Bishop Lazaril wants you to deliver the Light-infused Artifact to Velen in the Exodar.", progress = "My son, the lands of the humans and orcs have treated you well.  Such strength now swells within you...", completion = "Ah, I can see the power of the Naaru shine through this thing, as if Light itself is housed here.  Such good can be done with this implement; the necropolises sent from the frozen wastes of the north will surely fail.", sourceObjectiveStatus = "unverified-source-field" }
quests[12777] = { id = 12777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "My heart swells with Light to see you, a noble {race}, come to our aid.  Bless you, good {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12778] = { id = 12778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Apocalypse", description = "The trap has been sprung, death knight. The armies of Hearthglen and Tirisfal have arrived, just in time to see their enclave in flames! If they turn back now, they fight us with their backs turned.\n\n<Mograine shakes his head.>\n\nNo, they have only one option, which has only one outcome: APOCALYPSE!\n\nAs we speak, they prepare to make one final stand.\n\nThe Lich King awaits your return, champion. He stands watch below us, at Death's Breach.", sourceObjective = "Seek out the Lich King at Death's Breach.", completion = "You have served me well, {name}. The mark of the Scourge has been burned into these Scarlet lands. You have reaped death and destruction for as far as the eye can see and delivered to me the last of the Scarlet armies.\n\n\n\nIt is now time to finish what you started.", sourceObjectiveStatus = "unverified-source-field" }
quests[12779] = { id = 12779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End To All Things...", description = "You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, {name}.\n\n<The Lich King pauses.>\n\nThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.\n\nUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.", sourceObjective = "The Lich King has commanded you to eradicate the Scarlet Crusade.\n\nUse the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas. Avoid incoming projectiles by moving out of their line of fire!", progress = "Kill them all...", completion = "Kneel, champion. I place this helm upon your head to complete your terrifying visage. Any that dare look upon your dark countenance will know that death comes. Let none stand so boldly against your king so as to face your merciless wrath, {name}.\n\nThere remains only one final task...\n\n\n\nLight's Hope Chapel.", sourceObjectiveStatus = "unverified-source-field" }
quests[12780] = { id = 12780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRICATED>>Enemy of Our Enemy", description = "As much as we find working with death knights distasteful, we cannot afford to be picky about our allies here.\n\nWe're pinched between the Scourge and the savage Drakkari, who want nothing more than to destroy us so that they can get at one another.\n\nTravel west to Ebon Watch. Speak with Stefan and see if you can be of service to him.", sourceObjective = "Sergeant Riannah in Light's Breach wants you to speak with Stefan in Ebon Watch and offer your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12781] = { id = 12781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Siouxsie the Banshee in Ebon Hold.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!You will be able to choose one of these rewards:", sourceObjective = "Bring the Ebon Hold Gift Voucher to Siouxsie the Banshee in Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12782] = { id = 12782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  So, elf, as your race's self-proclaimed name implies... Do you have blood to spare?  Fresh blood is welcome blood indeed...", sourceObjectiveStatus = "unverified-source-field" }
quests[12783] = { id = 12783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine, robust specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  Fresh blood is welcome blood indeed, and the rage in your blood could fuel hours of research.", sourceObjectiveStatus = "unverified-source-field" }
quests[12784] = { id = 12784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine, robust specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  Fresh blood is welcome blood indeed, and I'm sure someone of your stature has blood to spare...", sourceObjectiveStatus = "unverified-source-field" }
quests[12785] = { id = 12785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.", progress = "Welcome to Orgrimmar, {name}.  Grand Apothecary Putress sent word ahead of you... do you have the infected brain?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12786] = { id = 12786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Bluff", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff.", progress = "Welcome to Thunder Bluff, {name}.  Grand Apothecary Putress sent word ahead of you... do you have the infected brain?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12787] = { id = 12787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Undercity", description = "The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...\n\nTake this -- it is a zombie's head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Master Apothecary Faranell in the Undercity.", progress = "Salutations, {name}.  You come from Shattrath?  You have instructions from Grand Apothecary Putress?", completion = "Ah, what a fine specimen you are.  The disease, -- diseases -- dancing through your brain must offer you visions so sublime.  We will spend long nights in conversation, you and I, and I will pick from you your thoughts as I slowly extract the meat from your skull.\n\nDo not fear, little one.  The knowledge gained from your sacrifice will be awesome.  You are a gift to the forsaken; you will herald a new age of respect for us among the peoples of this world.  Your place in our history is assured...", sourceObjectiveStatus = "unverified-source-field" }
quests[12788] = { id = 12788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermoon", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Tepesh.  She attends Lor'themar Theron in Silvermoon City.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Tepesh in Silvermoon City.", progress = "Welcome to Silvermoon, {name}.  Grand Apothecary Putress sent word ahead of you... do you have the infected brain?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12789] = { id = 12789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Breach!", description = "Ready yourself, {class}. I'm dispatching you to Light's Breach, northeast of here.\n\nI've received word that the Scourge are making a push to take over Zul'Drak.\n\n<Valus stares you dead in the eyes.>\n\nThis will not come to pass.\n\nSee to it that you assist in the destruction of the Scourge there. The light demands it.\n\nDismissed.", sourceObjective = "Crusader Valus at Light's Trust wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.", completion = "Excellent. Valus must have received my report.\n\nLet's get to work, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12790] = { id = 12790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Leave and Return: the Magical Way", description = "Just in case you don't already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.\n\nCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.\n\nI would like for you to do this now.", sourceObjective = "Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal.", progress = "I sense that you haven't yet tested out both of the teleport crystals.\n\nThat's alright, take your time.", completion = "Excellent, {class}. Now you know the way to get down to Crystalsong Forest and also how to return.", sourceObjectiveStatus = "unverified-source-field" }
quests[12791] = { id = 12791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", sourceObjective = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12792] = { id = 12792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Things First", description = "Listen up, {race}!\n\nThis entire region is full of crises. Everywhere you look you'll find those who could use your assistance.\n\n<Kunz looks you squarely in the eye.>\n\nNo one needs your help right now more than Riannah. The scourge have forced their way between us, leaving her and those she commands isolated.\n\nLight's Breach, where her forces are holding out, lies just southwest of here.", sourceObjective = "Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light's Breach.", completion = "My report must have made it through to Kunz.\n\nIt is good to know that he is well.", sourceObjectiveStatus = "unverified-source-field" }
quests[12793] = { id = 12793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke on the Horizon", description = "You hear that, {race}?\n\nThe clamor of battle far to the west reaches us here, even over the din of our own struggle.\n\nThe Scourge are threatening to break through the lines of those calling themselves the Argent Crusade. Preventing this is as urgent as anything in the region.\n\nTravel to Light's Breach and join in their struggle. Speak to Maaka and he will provide you safe passage.", sourceObjective = "Khufu in Zim'Torga wants you to travel to Light's Breach and report to Sergeant Riannah there.\n\nMaaka will provide you with transportation there.", completion = "The Light shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[12794] = { id = 12794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", sourceObjective = "Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12795] = { id = 12795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Stand", description = "A few moments ago I spotted a signal flare over the treeline to the east.\n\nThat can only mean that things are not going smoothly for the Crusaders at Argent Stand.\n\nI cannot leave our post here, {race}, but you can. When time permits, make your way up to Commander Falstaav and see if there's anything you can do to lighten their burden.", sourceObjective = "Bloodrose Datura at Ebon Watch wants you to speak with Commander Falstaav at The Argent Stand.", completion = "As it happens there is something you can do to be of assistance, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12796] = { id = 12796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", sourceObjective = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12797] = { id = 12797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Through the Waygate", description = "You speak the truth, {race}.  I can sense the very essence of Sholazar Basin begin to fray by the blight of undeath even as we speak.\n\nI've bound my being into the rune, {race}.  Deliver it to she who sent you here -- for only her power can grant me passage to her lands.", sourceObjective = "Bring the Omega Rune to the Avatar of Freya at the Rainspeaker Rapids in Sholazar Basin.", progress = "You've returned, {name}.", completion = "You've done well.\n\nWoe unto our enemies.  Woe unto those who serve the Lich King and threaten the titans' creations -- for the Etymidian is here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12798] = { id = 12798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swords Deck", description = "Now that you have gathered all of the Swords cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone.", sourceObjective = "Use the Swords Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Swords.  Excellent.", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[12799] = { id = 12799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siphoning the Spirits", description = "You should be happy he's coming, they said. You'll enjoy his company, they said....\n\nWell it's not as if I had a choice in the matter. Finklestein is the Crusade's best alchemist. I suppose I should be honored that he's chosen my post to set up shop. But ever since he's arrived, I've been relegated to collecting various alchemical ingredients.\n\nSay, {race}, how about you give me a hand? Just south of here are some pools that are haunted by spirits of ancient trolls. Collect their ectoplasm for me.", sourceObjective = "Captain Arnath at Heb'Valok wants you to collect 5 Ancient Ectoplasms from the Lost Drakkari Spirits at the Pools of Zha'Jin.", progress = "Good day, {race}.\n\nHave you collected the ectoplasm Finklestein asked for?", completion = "Thank you, {class}.\n\nThis should save my men some precious time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12800] = { id = 12800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Command", description = "The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend.\n\nWe now turn all of our efforts to Light's Hope Chapel. No longer will this affront to your master be allowed to exist!\n\nI have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill.\n\nDo not fail me, {name}.", sourceObjective = "Report to Scourge Commander Thalanor at Browman Mill.", completion = "The Highlord and the other death knights are preparing to strike! We will squeeze the last remnants of life out of this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[12801] = { id = 12801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light of Dawn", description = "The Argent Dawn stands defiantly against us at Light's Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed!\n\nThe mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes!\n\nWhen you are ready for battle, report to Highlord Darion Mograine. It is the highlord who will issue the final march orders and command our armies at Light's Hope Chapel.", sourceObjective = "Defeat the forces of the Argent Dawn and uncover the Light of Dawn.\n\nReport to Highlord Darion Mograine should you survive.", progress = "<Highlord Mograine nods.>", completion = "There will be no atonement for us, {name}. We are forever damned to walk the earth as monsters. While the Lich King may have loosed his grip upon us, the specters of our past will forever haunt our memories.\n\nWe must make amends in the only way we know how: Death...\n\nI ask you now to join me in Acherus as a Knight of the Ebon Blade. Together we will destroy the Lich King and end the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12802] = { id = 12802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Heart is in Your Hands", description = "<Drakuru's voice fills your mind.>\n\nHey, mon! Dis eye of da prophets be great! I been usin' it to watch ya and I see ya got da heart now! Not bad....\n\nNow ya just gotta bring it to my brazier at Drak'atal Passage, a short walk east of ya.\n\nYa must drink my elixir at da pedestal to summon me there. This time, ya need ta mix in some desperate mojo from the defenders there for it ta be workin'.", sourceObjective = "Drakuru wants you to bring the Heart of the Ancients to him at Drak'atal Passage.\n\nYou will need to collect 5 Desperate Mojo to use the elixir there.", completion = "Impressive, mon! Fate be kind in bringin' us together.\n\nSoon I be avengin' me bruddas by cleansin' Drak'Tharon, and you be awarded Drak'Tharon's greatest treasure.", sourceObjectiveStatus = "unverified-source-field" }
quests[12803] = { id = 12803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Force of Nature", description = "I'm not sure about what I saw while flying to the northeast, but to me it looked like a gigantic woman kicking some Scourge butt.\n\nI'd heard the professor talk about a certain \"lifewarden\"  appointed by the titans to look over Sholazar.  I might not be a titan historian, but it sounds like she fits the bill.\n\nI also know that if the Scourge cross the border between the Lost Lands and the rest of Sholazar, our expedition's as good as dead.  What do you say you go look for her and lend a hand?", sourceObjective = "Travel to the Blight Line, between Rainspeaker Rapids and the Lost Lands in Sholazar Basin and seek the Avatar of Freya.", completion = "You are not of this land.  But you also are not with the Scourge.\n\nWhat should I make of you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12804] = { id = 12804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steak Fit for a Hunter", description = "Sometimes, there's nothing worse than a camp full of hunters. They're all so busy taking down prey animals that the only meat I get is tough and stringy. That's hardly the kind of thing you want to come home to after a long day on the hunt.\n\nLucky for us, though, there is a source of tender, succulent meat nearby. To the south of the river and the camp live longneck grazers. They're a perfect source of meat for our hungry hunters. Bring me back the best cuts of meat and we'll properly toast our comrades.", sourceObjective = "Bring 5 Longneck Grazer Steaks to Korg the Cleaver at the Nesingwary Base Camp.", progress = "Did you get those steaks?", completion = "Now that's a meal! If anything good came of the shipwreck, it's got to be that we've been spared eating nothing but salt beef for the next month! Thank you again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12805] = { id = 12805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging Life's Strength", description = "The Lifeblood Pillar was toppled over with great force, sending the very earth into an upheaval.\n\nThe elementals that wander the sundered shard carry with them the very life essence that gave the pillar its strength.  I cannot allow this energy to be wasted, for only four pillars remain.\n\nHead to the sundered shard, to the southeast, and seek the lifeblood elementals.\n\nUse this gem on their remains to recover their rampant energy.  We'll need the energy to heal the land when all this is over.", sourceObjective = "The Avatar of Freya wants you to go to the Sundered Shard to the southeast and use the Lifeforce Gem on 8 destroyed Lifeblood Elementals.", progress = "Have you recovered the elementals' energy, {name}?", completion = "I thank you, {name}.  It is a shame that the pillar has fallen, but we must salvage what we can.", sourceObjectiveStatus = "unverified-source-field" }
quests[12806] = { id = 12806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rise with all Due Haste!", description = "Some would say that our most critical mission lies not with the Lich King, but with the utter destruction of the Scarlet Onslaught. I would say that is foolish, but who am I to judge?\n\nDeath's Rise is far to the southwest, overlooking the sea along the cliff wall. There you will find Lord-Commander Arete personally overseeing the Onslaught's destruction himself.\n\n<The baron clears his throat.>\n\nDo see to it that you report to him with all due haste. He asked for you personally.", sourceObjective = "Report to Lord-Commander Arete at Death's Rise in Icecrown.", completion = "It's about damned time! No doubt that Baron Sliver took his sweet time in sending you to me.\n\nI should have that empty space above his shoulders removed!", sourceObjectiveStatus = "unverified-source-field" }
quests[12807] = { id = 12807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story Thus Far...", description = "We have much to do, but first I believe a short refresher is in order.\n\nWe death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest.\n\nWhen you are ready for an earful, speak with me again and I shall provide enlightenment.", sourceObjective = "Listen to Lord-Commander Arete's tale at Death's Rise.", progress = "I suppose you think that you're ready to continue? How could you be though... you haven't yet heard the entirety of my tale!", completion = "In their folly, the Argent Crusade has chosen to turn a blind eye upon the presence of the Scarlet Onslaught. We will not.\n\nWe do not care if they might assist in the battle against the Lich King. We do not believe them worthy of existence. We will be their end, once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[12808] = { id = 12808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "Brother {race}, I am proud to stand with you during our days of need.  Bless you, and may the clever eyes of your race help find a path to our salvation..", sourceObjectiveStatus = "unverified-source-field" }
quests[12809] = { id = 12809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  High Tinker Mekkatorque in Tinkertown will be eager to make use of the artifact's power.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to High Tinker Mekkatorque in Ironforge.", progress = "Hello, {name}!  Look at you!  I see you have grown precisely one-point-seven-three microspans since last I saw you.  The airs of Outland have had an effect on you, I am certain of it.", completion = "Inconceivably immaculate!  This device stores Light energy at levels beyond those of any source yet known!  Oh, the possible applications shiver my whiskers and curl my toes.  Ho ho!  The anti-nocturnal photo-dispersement geno-actuator I could build with this would turn dusk into dawn!  The Scourge won't know what hit them.  We'll destroy them all in one pull of a lever!", sourceObjectiveStatus = "unverified-source-field" }
quests[12810] = { id = 12810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Water", description = "The forces at Onslaught Harbor are heavily reinforced by gryphon riders. You need a mount that will enable you to put them down. But first, we need the components for the ritual that is going to make it all happen.\n\nA great deal of blood is necessary for the ritual to be undertaken.\n\n<The lord-commander points down and to the northwest.>\n\nThere is a readily available supply down there in the harbor... sharks. Do not return to me until you've filled this bladder with their blood.", sourceObjective = "Lord-Commander Arete at Death's Rise wants you to fill the Gore Bladder with the blood of 10 Ravenous Jaws.", progress = "It's not glamorous work, but it is necessary.\n\nNow why is it that we are talking again before you are done, {class}?", completion = "Well done. Take a moment to let the saltwater dry from your skin before we continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[12811] = { id = 12811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine, robust specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  Fresh blood is welcome blood indeed, and your primal blood could fuel hours of research.", sourceObjectiveStatus = "unverified-source-field" }
quests[12812] = { id = 12812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Thrall in Orgrimmar.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.", progress = "Salutations, {name}.  You come from Shattrath?  You have instructions from Grand Apothecary Putress?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12813] = { id = 12813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Their Corpses, Rise!", description = "How kind... how generous our lord-commander is. Where he is flowers and sunshine, I am filled only with hatred.\n\nIt is not enough to end their miserable lives... I want them humiliated... debased!\n\nWhat could be more unspeakable than to be turned into that which you hate? To dedicate your existence to eradicating a thing, and then in the end to become it?\n\nHow sad.\n\nTake this tincture northwest to Onslaught Harbor. Apply it to their still corpses and watch what happens, but avoid the cathedral.", sourceObjective = "Setaal Darkmender at Death's Rise has given you the Darkmender's Tincture. Apply it to the corpses of 10 of any of the Scarlet Onslaught units found at Onslaught Harbor.", progress = "Surely you're not done so soon?", completion = "<The draenei death knight fixes you with a cold stare, her eyes dead as the grave. A sly grin creeps across her features.>\n\nI'll have more of the tincture prepared tomorrow. Until then, be well.", sourceObjectiveStatus = "unverified-source-field" }
quests[12814] = { id = 12814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Need a Gryphon", description = "What could be more fitting than to take one of their own gryphons to use against them? Go to Onslaught Harbor and take the reins to one of their gryphons from the dead clutches of its rider.\n\nReturn with the gryphon, delivering it to Uzo Deathcaller. He will see to its proper transformation and provide you with further instructions.", sourceObjective = "Deliver an Onslaught Gryphon to Uzo Deathcaller at Death's Rise.", progress = "What took so long? Are their gryphons slow? We'll have to do something about that!", completion = "Oh yeah this is gonna be good!\n\nStand back... I'm gonna call down the wrath of the blood ritual!", sourceObjectiveStatus = "unverified-source-field" }
quests[12815] = { id = 12815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Fly Zone", description = "Now that you got your bone gryphon, I wantcha to take it back down there everyday and make a no fly zone over Onslaught Harbor.\n\nI gotta admit, mon, I don't really care if you use the bone gryphon to kill them gryphon riders or not. But I'm guessin' that if you do, you'll find it much easier to get to 'em.\n\nBesides, it's got lots of neat tricks you can use.", sourceObjective = "Uzo Deathcaller at Death's Rise wants you to kill 10 Onslaught Gryphon Riders.", progress = "What you back so soon for? I know I can still see those Onslaught boys still flyin' around down there!", completion = "That's the spirit! And you know, I need this done every day that we're here.\n\nI hope you'll come back again tomorrow. Your bone gryphon will be waitin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[12816] = { id = 12816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Silvermoon", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Silvermoon from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", sourceObjective = "Collect three Dim Necrotic Stones from the Scourge outside Silvermoon and investigate the glowing runic circles near their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[12817] = { id = 12817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Exodar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Exodar from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", sourceObjective = "Collect three Dim Necrotic Stones from the Scourge outside the Exodar and investigate the glowing runic circles near their encampment. Then return to Lieutenant Kregor.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[12818] = { id = 12818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up", description = "To the point... Ricket's asked me to put together some stronger land mines, but I'm running low on parts.\n\nJust west of town, you'll find the remains of our last rocket sled... Ricket got a little excited when she was fueling it, but I probably should have thought to not put the nozzle right over the exhaust. Live and learn, eh?\n\nThere should be a good stock of spare parts scattered around the destroyed sled... why don't you go ahead and chase off those scavengers and nab me some of that wreckage?", sourceObjective = "Jeer Sparksocket at K3 would like 10 pieces of Charred Wreckage.", progress = "We have to have something we can use to insulate our engines against this cold... think, Jeer, think!\n\nOh hey! Did you get some of that wreckage for me?", completion = "These will do nicely, thanks!\n\nDid you happen to see Dim out there? I sent him out a long while back and he never came back. I hope he's alright.\n\nSpeaking of which... I wonder where Janks is...", sourceObjectiveStatus = "unverified-source-field" }
quests[12819] = { id = 12819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Around the Corner", description = "Blast it! Where are my tools? I had them here just a moment ago.\n\nOh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out.\n\nOh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.", sourceObjective = "Jeer Sparksocket at K3 would like Sparksocket's Tools retrieved from his minefield.", progress = "If Janks were here, I could have just sent him on this errand. Oh... on second thought... I'm not sure I told him where the safe path is anyway.\n\nGood thing I have you resourceful adventure types around, eh?", completion = "Ha ha! These are them! Thank you kindly. I hope you didn't have too much trouble traversing the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[12820] = { id = 12820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delicate Touch", description = "I've been waiting an eternity for these mines! Well, a few days at least. What took him so long?\n\nHere's the low down, compadre... there's this nasty bunch of magnataur--you know, big, hairy, and extremely ugly--and they seem pretty keen on taking K3 for themselves.\n\nNot going to happen.\n\nWe've got some defenses set up in their path, northeast of here. Sadly, our laser turrets have pretty limited power supplies... that's where these mines come in! Get over there and blow them up good!", sourceObjective = "Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off 12 attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.", completion = "So... here I sat, basking in the awesomeness that is me, and in the distance, I hear a pop! Then another! Then a dozen more! And a smile crept onto my face at the thought of all those magnataur and snobolds eagerly rushing to their own deaths.\n\nWas it glorious?", sourceObjectiveStatus = "unverified-source-field" }
quests[12821] = { id = 12821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cell Block Tango", description = "The sapper squad is ready. That means it's time for fun!\n\nThere's only one thing holding us up from our full-scale assault on Garm! I sent a runner to set a teleporter up behind him--successfully I might add--and he returned to get the power cell it needs to function. It isn't working yet... which means the power cell didn't get there.\n\nI need you to look just on the other side of Garm's Bane for the power cell. When you find it, bring it farther east to Garm's Rise and activate the teleporter.", sourceObjective = "Ricket at K3 would like you to locate the Transporter Power Cell and use it to activate the Transportation Pad at Garm's Rise.", progress = "Even magnataur should know not to mess with goblins!", completion = "Excellent!\n\n<A fierce grin creeps onto Ricket's face.>\n\nLet the destruction begin!", sourceObjectiveStatus = "unverified-source-field" }
quests[12822] = { id = 12822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know No Fear", description = "Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!\n\nHahah, I had you going there for a moment, didn't I? You've got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won't have anywhere to run.", sourceObjective = "Ricket at K3 wants you to kill 6 Garm Watchers and 8 Snowblind Devotees.", progress = "Nothing strikes fear into the enemy quite like a goblin sapper!", completion = "Haha! That'll teach those brutes to waste our time. From this day forth, green skin will strike fear into the hearts of all magnataur!", sourceObjectiveStatus = "unverified-source-field" }
quests[12823] = { id = 12823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flawless Plan", description = "Hey there! Joining us for the assault I assume?\n\nI've got a special task for you... we're going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut's Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.\n\nOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There's no knowing how long the cave will last once that thing goes off!", sourceObjective = "Gino at Garm's Rise wants you to plant the Hardpacked Explosive Bundle near Frostgut's Altar, kill Tormar Frostgut, and then escape the cave before it collapses on you.", progress = "That explosive bundle is my baby... it took me weeks to perfect it. WEEKS!\n\nThat's a long time... okay.", completion = "The whole mountain shook! Was it gorgeous? I bet it was! How could it not be?\n\nAnd the Inventor's League tells me all of my inventions just blow up. Darn right they do! Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[12824] = { id = 12824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolitionist Extraordinaire", description = "You've got some swift feet on you sonny! Thanks for lending a hand with those explosives... I've been waiting to give that invention a good test run for a while!\n\nGo ahead and tell Ricket we should be covered on the magnataur front now... my sappers will clean up any of the remaining baddies.\n\nThanks again!", sourceObjective = "Return to Ricket at K3.", completion = "You blew the whole place up? Way to go! I bet Gino got a kick out of that.\n\nWe really appreciate all of the help you've lent us, {name}. How 'bout a souvenir for your troubles?", sourceObjectiveStatus = "unverified-source-field" }
quests[12825] = { id = 12825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expressions of Gratitude", sourceObjective = "[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[12826] = { id = 12826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slightly Unstable", description = "Looking good!\n\nNo, not you - my new mines. You're just a little full of yourself, aren't you? I, on the other hand, am absolutely brilliant! My intellect cannot be matched.\n\nWhat were we talking about? Oh yes, my new mines! New and improved... ready for whatever devious use Ricket has concocted.\n\nBe a <good lad/doll> and go hand them off to Ricket, will you? She's right over there... it should be quite the epic journey, I'm sure. Be careful though, she's a little loopy.", sourceObjective = "Deliver Jeer's Improved Land Mines to Ricket in K3.", progress = "Jeer finished the mines? Dandy.", completion = "Well, aren't these just the cutest little packets of destruction you've ever seen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12827] = { id = 12827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Rations", description = "Hey hey! You're a new face! Care to lend Ricket a hand?\n\nWe have a somewhat unexpected problem - food shortage. I know, I know... we should have seen that coming, but you don't get it. We tend to have somewhat of a quick turn-around here with our sapper squad and all, so usually we don't have to worry about long term eats. Good old K3's gotten popular though.\n\nConvenient solution? There are gnoll camps to the west and some gnolls scattered, scavenging as gnolls do. Care to go nab some of their rations?", sourceObjective = "Ricket at K3 wants you to repossess 16 Dried Gnoll Rations from the nearby Savage Hill Gnolls.", progress = "Hey there again! My belly's rumbling... how'd it go?", completion = "I hope they weren't too hesitant to share the wealth. We've been pretty forgiving with them picking through our leftovers thus far.", sourceObjectiveStatus = "unverified-source-field" }
quests[12828] = { id = 12828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ample Inspiration", description = "Wow! That stuff is nasty. Not to account for gnoll taste or anything, but I figured whatever they had would at least be... edible?\n\nLet's get more creative.\n\nTore's got an explosive dispenser north of town... not far from the big cavern entrance, can't miss it. I'm sure she intends them for mining purposes of some sort, but I've got a better idea.\n\nGrab one of those things and rush it to one of the nearby mammoths... most of them are to the west. Collect the meat, bring it back.", sourceObjective = "Ricket at K3 wants you to retrieve a U.D.E.D, use it to blow up a mammoth, and retrieve 8 Hearty Mammoth Meat.", progress = "I know my plan was brilliant. Don't even worry about it.\n\nDoes it feel good to be in the presence of greatness? A little tingly maybe?", completion = "And it's already well-done! I outdo myself sometimes.\n\nThanks much, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[12829] = { id = 12829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving In", description = "Hiya! The name's Tore. I  head up the mining operation here at K3... or I will shortly anyway!\n\nThis here cave is full of creepy-crawlies. I think we could do with a few less spiders before we move in - what'd you think?", sourceObjective = "Tore Rumblewrench outside of Crystalweb Cavern wants you to kill 12 Crystalweb Spiders.", completion = "Ha ha! Good to see you're up for some dirty work.\n\nMuch appreciated there, pal!", sourceObjectiveStatus = "unverified-source-field" }
quests[12830] = { id = 12830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ore Repossession", description = "We're moving in!\n\nThere were some snobolds here when we arrived... their mining operation seems to have met some unfortunate happenings though. Doesn't much matter - we were taking over soon anyway.\n\nI sent some of our miners in there to get me some ore samples that I can use to calibrate our machines for processing, but they haven't come back.\n\nMind going in there and nabbing some samples for me in their stead? The snobolds probably have some on them, though I'd expect most of them are dead by now.", sourceObjective = "Tore Rumblewrench outside of Crystalweb Cavern would like you to retrieve 5 samples of Impure Saronite Ore.", progress = "Ya have some ore for me?", completion = "Woo! That's a ripe stench right there! You had to get hands-on with some of those snobolds, didn't ya?\n\nI do appreciate it though!", sourceObjectiveStatus = "unverified-source-field" }
quests[12831] = { id = 12831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Partly Forgotten", description = "Oi... it's like there's a propeller in my stomach.\n\nI think I can walk, but I got something nasty in my system when I got bit by something in the back of the cave. It was bigger than the other spiders... and brightly colored.\n\nRicket can probably make me an antidote, but she'd need the venom sac from whatever bit me. Would you mind finding it for me? I don't think Tore's coming.\n\nI'll just pretend I'm dead here and hopefully they'll leave me alone.", sourceObjective = "An Injured Goblin Miner in Crystalweb Cavern wants you to bring back an Icetip Venom Sac from an Icetip Crawler.", progress = "<The Injured Goblin Miner writhes in pain.>", completion = "That should cut it... I hope Ricket can put something together for me. Ready to get out of there, then?", sourceObjectiveStatus = "unverified-source-field" }
quests[12832] = { id = 12832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitter Departure", description = "Oi - thank you! I thought for sure I'd just be a spider snack. Perhaps I'm speaking a bit soon though - let's get the heck out of here!\n\nLet me know as soon as you're ready to go... make it quick.", sourceObjective = "Escort the Injured Goblin Miner out of Crystalweb Cavern and then speak to Ricket at K3.", completion = "Thanks for helping out our miner back there, {name}! I should be able to put together an antidote no problem.\n\nIf you stumble into Tore again, tell her that she's a jerk for me, will ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[12833] = { id = 12833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overstock", description = "Hey there again! You didn't run off like all the other adventurers did? Well, you're just a peach, aren't ya? I was beginning to think I smelled funny or something!\n\nWe could still use a bit of a hand around here, and you have just the right experience.  Remember those magnataur? Well apparently the cave didn't completely collapse... there are still quite a few left. So much for Gino taking care of them, eh?\n\nFortunately, Jeer made way more than enough mines. You've got this!", sourceObjective = "Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off the attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.", completion = "I like you. In fact, you rock!\n\nYay for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12834] = { id = 12834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Rain, Nor Snow, Nor Exploding Plane", sourceObjective = "[PLACEHOLDER] Test cold-weather bomber on giant.", sourceObjectiveStatus = "unverified-source-field" }
quests[12835] = { id = 12835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Grown Up", sourceObjective = "[PLACEHOLDER] Test Grown Up Jormungar on Giant", sourceObjectiveStatus = "unverified-source-field" }
quests[12836] = { id = 12836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expression of Gratitude", description = "I know just the job for an eager newcomer! We've got a gnoll problem. You might even call it a gnoll infestation! Pesky things. They keep creeping up more and more, and now they're on our doorstep, stealing our parts! Inconceivable.\n\nIt all begins and ends with their uppity leader, Gnarlhide. I want you to see to that \"ends\" part. Go pay him a visit at his camp all the way to the west, in Snowblind Hills.\n\nAnd when I say \"pay him a visit,\" that's a euphemism for \"kill him painfully.\" Kay? Kay!", sourceObjective = "Ricket at K3 wants you to kill Gnarlhide.", progress = "I like Ricket cause she's sooo delicious!\n\nOh, hey there again! How goes the pest control?", completion = "Groovy! You're my kind of {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12837] = { id = 12837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore's Got the Goods", sourceObjective = "[PLACEHOLDER] Report to Tore", sourceObjectiveStatus = "unverified-source-field" }
quests[12838] = { id = 12838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intelligence Gathering", description = "I need to know what the Scarlet Onslaught is planning today. You will be my instrument in this task.\n\nFly to Onslaught Harbor and rifle through their baggage trunks for documents. The trunks will be locked, so you'll have to take the keys from the Scarlet Onslaught members by whatever means.", sourceObjective = "Aurochs Grimbane at Death's Rise wants you to collect 5 Onslaught Intel Documents.", progress = "You have information for me?", completion = "Hand them over. I will sift through the useless ones and if there's anything actionable, I will call upon you.\n\nEither way, return tomorrow. It is well known that they change their plans on a daily basis.", sourceObjectiveStatus = "unverified-source-field" }
quests[12839] = { id = 12839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand (Admiral's) Plan", description = "At first this note looks like any of the other intel that you've been looking for. However, a quick perusal of its contents disabuses you of this notion.\n\nThe letter conveys that Grand Admiral Westwind is present somewhere on the island, but that he is keeping himself secluded for now. He speaks of a glorious day that is coming soon in which the Scarlet Onslaught will wash over first the Lich King and then the rest of world to finally bring order to Azeroth.\n\nThe lord-commander will want to see this!", sourceObjective = "Deliver the Note from the Grand Admiral to Lord-Commander Arete at Death's Rise.", progress = "Scarlet Onslaught intel is to be delivered to Aurochs Grimbane.\n\n<The lord-commander gives you an expectant look by way of a dismissal.>", completion = "A note written by Westwind? Why didn't you say so?\n\n<Arete tears the letter from your hand to read it.>\n\nThe fool! He's actually here?!\n\n<The lord-commander laughs.>\n\nThis is new information. I wonder how he imagines that he's going to conquer the world once he's taken down the Lich King? Not that he could accomplish either task in his wildest imaginings.", sourceObjectiveStatus = "unverified-source-field" }
quests[12840] = { id = 12840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Strict Confidence", description = "If anyone knows where the admiral is, then surely it must be his captains on the ships in Onslaught Harbor.\n\n<The lord-commander rubs his hands together.>\n\nWelsington and Hartford are their names if memory serves. Go beat the information out of them and then end their miserable lives.\n\nI want to know where the grand admiral is hidden!", sourceObjective = "Lord-Commander Arete at Death's Rise wants you to beat information out of Captains Welsington and Hartford.", progress = "Where is Grand Admiral Westwind?", completion = "They resurrected Landgren? He's the one that will know where the grand admiral is then!", sourceObjectiveStatus = "unverified-source-field" }
quests[12841] = { id = 12841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crone's Bargain", description = "Yes, it must be the little green prisoner you're after...  We might be able to help each other.\n\nYou're not going to get the goblin out of here by force. Not alive, anyway.\n\nAmong my people I am known as a Yrkvinn, a practitioner of illusions. As you can see, the Hyldnir have made me their prisoner.\n\nIf I had my runes, I could make you go unnoticed among them. Further inside, patrolling the mines, you'll find an overseer named Syra. She has my runes. Retrieve them and we'll talk some more.", sourceObjective = "Lok'lira the Crone inside the Forlorn Mine wants you to retrieve the Runes of the Yrkvinn from Overseer Syra.", progress = "My runes, {name}?  Do you have them?", completion = "I wasn't sure you were coming back.  I dread to think what will happen to me if I stay here for much longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12842] = { id = 12842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runeforging: Preparation For Battle", description = "The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry.\n\nPreparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power!\n\nReturn to me when your blade glows with dark energy!", sourceObjective = "Instructor Razuvious in Ebon Hold has commanded you to use your Runeforging ability to engrave a rune [of your choosing] upon your Runed Soulblade.\n\nYou may freely replace the engraving upon your weapon at any time, so long as you are near a Runeforge.", progress = "Do not waste time, {name}. We are on the brink of apocalypse!", completion = "Remember these words, {class}: The Runeforge is a Scourge instrument. It exists only in Acherus, Naxxramas and the heart of Icecrown! You may only emblazon your weaponry at a Runeforge.\n\nReturn often and emblazon all of your weapons. A {class} must be prepared for all that would dare oppose him!", sourceObjectiveStatus = "unverified-source-field" }
quests[12843] = { id = 12843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took Our Men!", description = "You have to help us!  We were in the middle of an expedition into the mountains to set up a transmission tower when we were attacked.\n\nThey looked like vrykul, except their skin was blue and layered with frost... and they were all female!  They took all the men in the expedition and let us women go.  Please, {name}!  We think they're being held in Sifreldar, the village overlooking K3.", sourceObjective = "Gretchen Fizzlespark wants you to go to Sifreldar Village and rescue 5 Goblin Prisoners.", progress = "Did you find our men, {name}?", completion = "You did it!  Our boys are back!", sourceObjectiveStatus = "unverified-source-field" }
quests[12844] = { id = 12844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Recovery", description = "Please, {name}.  When the Hyldnir took our men, they also took all our equipment.  Of course, it's more important that we get our boys back, but if you run into any of our equipment, I'd really appreciate it if you brought it back to us.\n\nYou'll find their village just above us, to the north.", sourceObjective = "Gretchen Fizzlespark wants you to obtain 8 pieces of K3 Equipment in Sifreldar Village north of K3.", progress = "Any luck with our equipment, {name}?", completion = "Thanks, {name}!  We'll see what we can do to salvage these parts!", sourceObjectiveStatus = "unverified-source-field" }
quests[12846] = { id = 12846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Goblin Behind", description = "All of our boys are back... thanks to you, {name}!  Well... all but one.\n\nMy brother Zeev is still up there according to the others.  Apparently they have some sort of mine where they make their prisoners work.  Go in there and see if you can find out anything.", sourceObjective = "Find the entrance to the Forlorn Mine in northern Sifreldar Village and look for clues for Zeev Fizzlespark's whereabouts.", completion = "You're definitely not with the Hyldnir... so what are you here for?  Ah... you must be looking for the new prisoner!", sourceObjectiveStatus = "unverified-source-field" }
quests[12847] = { id = 12847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Chances", description = "I'd heard they have an archbishop in their cathedral, but I had no idea that they'd resurrected and promoted Landgren! The Crimson Cathedral is heavily guarded with only one entrance, so you'll need help.\n\nWe still need to know where the grand admiral is, but this time we're not taking any chances!\n\nTake this device. It can be used to summon a gate for me to step through once you've killed the archbishop.\n\nI'll have my answers directly from his compelled soul! We will find Grand Admiral Westwind!", sourceObjective = "Kill Archbishop Landgren and then summon Arete's Gate in the presence of his corpse. Speak with Lord-Commander Arete inside The Crimson Cathedral once he's completed his questioning of the archbishop's spirit.", progress = "Yes?", completion = "Hidden caves on the backside of the island. How very interesting.\n\nWell, at least now I know where all of my missing spies are.", sourceObjectiveStatus = "unverified-source-field" }
quests[12848] = { id = 12848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Hunger", description = "The endless hunger will soon take hold of you, {class}. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated.\n\nI give you the key to your salvation.\n\nChained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate. Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity.\n\nLive or die - the choice is yours to make.", sourceObjective = "Instructor Razuvious in Ebon Hold has commanded you to free an Unworthy Initiate and then kill the Unworthy Initiate in cold blood!\n\nIt's your life or theirs!", progress = "Two lives, one key... Do not fail me, {name}.", completion = "As expected, my chosen knight has triumphed! You are ready, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12849] = { id = 12849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Of Blood, Frost And Unholy", sourceObjective = "Within the Hall of Command you will find the schools of blood, frost and unholy. Each school has a trainer that can provide you with knowledge in the various dark arts.\n\nI, Lord Thorval, am the headmaster of the school of blood. Lady Alistra reigns over unholy and the arch-lich, Amal'thazad, holds dominion over frost.\n\nYou must return here whenever you gain power and train!", sourceObjectiveStatus = "unverified-source-field" }
quests[12850] = { id = 12850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report To Scourge Commander Thalanor", description = "Scourge Commander Thalanor awaits your arrival at the overhang located directly southeast of our current position. Report to Thalanor and requisition a Scourge gryphon to deliver you to Death's Breach.\n\nPrince Valanar will be waiting for you down below.\n\nSuffer well, <brother/sister>!", sourceObjective = "Report to Scourge Commander Thalanor at the balcony on the first floor of Ebon Hold.", completion = "The war has begun, {class}! I shall place you upon my finest gryphon and deliver you to Death's Breach. Chaos, death, destruction! You will herald in all of this and more!", sourceObjectiveStatus = "unverified-source-field" }
quests[12851] = { id = 12851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearly Hanging On", description = "The test awaits, woman!\n\nDo you have the heart of a warrior queen? Or that of a sniveling seamstress?\n\nOne taste of war and you'll know the answer.\n\nYou might lie to your mother, your sisters, and even yourself, but the battlefield always exposes one's true nature.\n\nWhen you've made your preparations, mount Icefang and ride into battle. From her back, you must rain down a shower of death upon our enemy.", sourceObjective = "Brijana at Brunnhildar Village wants you to mount Icefang and shoot 7 Frostworgs and 15 Frost Giants in the Valley of Ancient Winters.", progress = "Have you survived the battle, {name}?", completion = "Perhaps you do have the heart of a warrior.\n\nTime will tell...", sourceObjectiveStatus = "unverified-source-field" }
quests[12852] = { id = 12852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral Revealed", description = "When High General Abbendis was confronted at New Hearthglen, the grand admiral protected himself within an impenetrable sphere of magic before making his escape.\n\nI am particularly adept at nullifying magic.\n\nTake this to use against him inside The Hidden Hollow when he puts the sphere up. I wish that I could be there to see the look on his face when you do it.\n\nDeal with him.", sourceObjective = "Lord-Commander Arete wants you to deal with Grand Admiral Westwind. Return to the lord-commander upon Death's Rise after you have done so.", completion = "MAL'GANIS?!!\n\n<The lord-commander laughs with abandon.>\n\nThe fools were taken in by the demons yet again and now they are destroyed!\n\nI trust that my favorite {class} will stick around long enough to help us finish off the rest of them? Perhaps one of these would convince you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12853] = { id = 12853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luxurious Getaway!", description = "Hey there, pal!\n\nDo you like excitement and explosions?! Who doesn't? I know just the place for you. Down at luxurious K3, they're always making innovative inventions and finding all-new ways to make things blow up! Sounds thrilling, doesn't it? If you want to be part of the fun, head on down today and speak to Jeer Sparksocket!\n\nMandatory disclaimer: manual labor may be required to partake in previously indicated \"excitement.\"", sourceObjective = "Speak to Jeer Sparksocket at K3 in the Storm Peaks.", completion = "Welcome to K3!\n\nWe came here to make our way into those peaks and get our fair share of some of those amazing titan machines. Progress on that end has been somewhat minimal, though. Gnolls, snobolds, magnataur... there's no shortage of trouble to go around... not to mention, we can't seem to keep any fliers in the air without their motors freezing.\n\nThere's plenty of work to be done though - lend a hand, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12854] = { id = 12854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Brann's Trail", description = "After the discovery of Brann's journal in Grizzly Hills, we've only had one other communication from Brann. A mysterious note found its way to Explorers' League headquarters in Ironforge, with no indication of where it came from. All it said was that we're to meet Brann at his camp and help him with his search.\n\nFrom what I can tell, the camp should be located northeast of here, across the Bor's Breath River and at the foot of some ruins from the Path of the Titans.", sourceObjective = "Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Archaeologist Andorin at Frosthold.", progress = "Did you find Brann's camp?", completion = "<Archaeologist Andorin looks at you expectantly.>\n\nYou were supposed to come back with Brann, not a piece of paper. What's going on here?", sourceObjectiveStatus = "unverified-source-field" }
quests[12855] = { id = 12855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Out the Perpetrator", description = "The tone of Brann's note suggests he meant to bury something with the note, maybe a pack of some kind. You're sure this was all you found?\n\nOkay, I'm going to have you take one of these frosthounds with you. The frostborn use them for tracking. Bring it to the destroyed camp and let it get Brann's scent.\n\nIt should at least lead you to the location of those missing possessions, and if we're lucky, Brann himself.", sourceObjective = "Use the Frosthound Collar at the Abandoned Camp to track down whoever took Brann's possessions. When you recover them, use the communication device and speak to whoever you can contact.", progress = "Who are you?", completion = "You... you're not a member of the Explorers' League, at least not one I remember. But, if you recovered the communicator, they must've sent you. Good, that's almost what I was hoping for.", sourceObjectiveStatus = "unverified-source-field" }
quests[12856] = { id = 12856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Hearted", description = "To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....\n\nYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate our captive proto-drakes. With them, you will be able to free our sisters from their frozen bonds and carry them safely home.\n\nBeware the giants' clubs, sister, lest you find yourself numbered among the captives.", sourceObjective = "Free 3 Captured Proto-Drakes and rescue 9 Brunnhildar Prisoners.", progress = "Was your mission successful, sister?", completion = "Your efforts appear to have been successful, sister.\n\nYou have brought glory to the Brunnhildar!", sourceObjectiveStatus = "unverified-source-field" }
quests[12857] = { id = 12857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Ragemane's Flipper", description = "Posted by Chief Rageclaw:\n\nChief Rageclaw trusty lion seal, Ragemane, bite hand that feed him. Rageclaw say Ragemane no more good because of bad Drakuru trolls. Chief Rageclaw very sad to ask that Ragemane be killeded and Ragemane flipper be returned to chief as proof.\n\nYou find Ragemane to southeast, at Rageclaw Lake.\n\nChief Rageclaw sorry for bad writing. First time use one of these things; plus, Chief Rageclaw is wolvar, not person.", sourceObjective = "Recover Ragemane's Flipper and return it to Chief Rageclaw at Light's Breach in Zul'Drak.", progress = "Poor Ragemane. He was gift from brother-in-law.", completion = "<Chief Rageclaw cries.>\n\nHad Ragemane since pup. Sad day for Rageclaw. First troll attack Rageclaw, then troll make Ragemane bad. Rageclaw never trade with troll again!", sourceObjectiveStatus = "unverified-source-field" }
quests[12858] = { id = 12858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces to the Puzzle", description = "Thank the Light that someone got my message. Now that I'm safe from the iron dwarves, I need to ask your help with something. I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.\n\nOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians.", sourceObjective = "Gather 6 Inventor's Disk Fragments and use them to assemble the Inventor's Disk.", progress = "Did you complete the disk?", completion = "Wonderful! Now that we have the disk, you must use it to open the Inventor's vault!", sourceObjectiveStatus = "unverified-source-field" }
quests[12859] = { id = 12859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Just In: Fire Still Hot!", description = "Trolls attack Rageclaw Den and kick Rageclaw out! It get worse. Trolls now burning village! This very bad. Chief make top Rageclaw shaman, Moky, do study on fire. Results very surprising! Fire still hot and can burn things.\n\nWill you help Rageclaw and put fire out? Moky has special Rageclaw fire extinguisher for you. Use special fire extinguisher to put out fire at Rageclaw Den to southeast. Sometimes take many sprays to douse fire, but extinguisher always have water! Rageclaw magic strong!", sourceObjective = "Elder Shaman Moky at Light's Breach in Zul'Drak wants you to use the Rageclaw Fire Extinguisher to douse 15 hut fires at Rageclaw Den.", completion = "It strange because I know you put fire out, but fire still burning. Maybe this thing not so good after all, eh? Still, Moky pay you for what you do! Hopefully troll burn too!", sourceObjectiveStatus = "unverified-source-field" }
quests[12860] = { id = 12860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Mining", description = "That disk you assembled... it's blank! That crafty Mimir must've hidden the information somewhere else. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be what you need to do with the disk. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", sourceObjective = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not! You have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Mimir to be systematic. Can't say that for the rest of these Keepers from what I've been hearing...", sourceObjectiveStatus = "unverified-source-field" }
quests[12861] = { id = 12861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls Is Gone Crazy!", description = "Drakuru... You know who this troll is? I think bad troll are controlled by the Drakuru troll. They call themself Drakuru trolls - that how I know. Now you see why I am chief of Rageclaw. Smartest of all wolvar!\n\nBut that not why I talk to you now. Bad troll come and kick Rageclaw out of den. Rageclaw that no run away held as prisoner in village. You go to Rageclaw Den, southeast, and free captured Rageclaw. Kill troll for lock opener. You maybe kill many troll for many lock opener.", sourceObjective = "Chief Rageclaw at Light's Breach in Zul'Drak wants you to use the Drakuru \"Lock Openers\" found on various Drakuru trolls to free 8 Captured Rageclaw.", completion = "Rageclaw thank you, {name}. Though Rageclaw Den probably lost forever and troll-Rageclaw friendship also lost forever... and also now I think of it, Ragemane lost forever too. Also brother-in-law. He gone. Hrm, have you seen Chief's mate? I think she gone too.\n\nMaybe you go now. Chief a little depressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12862] = { id = 12862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", sourceObjective = "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks.", completion = "Ow! That looked painful. It was a pretty grand entrance though, lad!\n\nWelcome to Frosthold! Are ya here to help us find a path into Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[12863] = { id = 12863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offering Thanks", description = "Ah! Thanks for coming up here, <lad/lass>.\n\nJudging by your wide eyes and shivering hands, I'd venture a guess that you're somewhat new. Sounds like it would be good for you to meet our gracious hosts then!\n\nWe've got some extra medical supplies... to be honest, we weren't expecting to have such a comfortable setup. Go ahead and give this crate to Glorthal over there, and lend them a hand if you would too. We don't want them to think we're ungrateful for how welcoming they've been.", sourceObjective = "Bring the crate of medical supplies to Glorthal Stiffbeard in Frosthold.", progress = "Hello.", completion = "Medical supplies? Thank you! Not exactly sure what to do with them to be honest, but I'm sure they'll be useful.\n\nIt's good to meet you... there's such a colorful variety among your peoples. We're not used to having visitors up this way very often - it's good to have some fresh company.", sourceObjectiveStatus = "unverified-source-field" }
quests[12864] = { id = 12864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Scouts", description = "There is something that I could use a hand with now that I have you.\n\nWe have a few scouts that are extremely late in returning. The peaks are harsh... but these boys know what they're doing.\n\nHead to the east... along the Bor's Breath valley and near Bor's Fall... they should be out that direction. If you find any sign of one of them, bring me back news immediately. We have a few enemies in the area - if any of them are getting a bit uppity, the more warning the better.", sourceObjective = "Glorthal in Frosthold has requested a search of the Bor's Breath valley and Bor's Fall for any sign of the missing Frostborn Scouts.", completion = "When a scout doesn't come back for this long... that's about the expected result. The harpies then?\n\nKing Stormheart has us train hard year round... he's turned us into amazing fighters. At times like this, I understand why it's necessary. He's the wisest and strongest leader I've yet seen among our people... don't let his peachy skin fool ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[12865] = { id = 12865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Companions", description = "Fresh blood! Good to meet ya! I've got some work if you've got some time.\n\nOff to the east are the Foot Steppes... pretty hard land, but there's quite a group of rhino that graze there. Our birds have a taste for that rhino meat, but it's always a bit dangerous for them to go hunting with all of the proto-drakes that nest around there.\n\nIf you're keen, head over that way and get some rhino meat, bring it back to the peaks above here, and then use it to feed some of the eagles that nest there.", sourceObjective = "Fjorlin Frostbrow at Frosthold wants you to obtain 8 slabs of Fresh Ice Rhino Meat and use them to feed the Stormcrest Eagles above town.", progress = "These birds have been loyal to us for a long time... we get on pretty well.", completion = "Thank you, kindly... and I'm sure they're quite appreciative too. They make powerful allies; you'll be well off being on this side of their graces.", sourceObjectiveStatus = "unverified-source-field" }
quests[12866] = { id = 12866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemming the Aggressors", description = "Damn harpies. We've beat that bunch into submission more times than I can remember... and they stay quiet for a time after each bout. This time, I'd thought that maybe it sunk in.\n\nApparently not.\n\nTheir memory may be a bit short, but if their numbers are thinned enough, they'll keep to themselves. Head into the valleys in the north and east and clear out a fair chunk of them for me, will ya?", sourceObjective = "Glorthal Stiffbeard at Frosthold wants you to kill 8 Frostfeather Screechers and 8 Frostfeather Witches.", completion = "It's dirty work, I know, but we appreciate it. Now what was the name the scout mentioned... Sirana?", sourceObjectiveStatus = "unverified-source-field" }
quests[12867] = { id = 12867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby Stealers", description = "A few weeks ago, if you looked up, you'd see dozens of those beautiful eagles soaring the skies. Now, only a few if any. They've taken to staying with their nests nearly all the time now because the harpies have been stealing their eggs.\n\nThe harpies have grown a taste for eagle flesh, it seems... the sick wretches are caring for the eggs long enough to feast on the hatchlings. Go into the valleys to the north or the east and find the eggs... bring them back here, and I'll take them back to the nests.", sourceObjective = "Fjorlin Frostbrow at Frosthold would like you to bring back 15 Stormcrest Eagle Eggs.", progress = "We'll get this harpy problem taken care of... the eagles will be free to soar the skies again soon.", completion = "Good stuff, lad. You're making fast friends.\n\nIf you stop back by soon, I'm sure we can find one that will let you ride... they should know that you're trustworthy now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12868] = { id = 12868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirana Iceshriek", description = "This Sirana Iceshriek sounds like the one that's spurring the harpies to be more aggressive. If we kill her, I suspect their attacks won't last long afterwards.\n\nOne of our stormriders claims to have spotted her circling the peak directly northwest of here.  Go find the wench and put her down. Let's see this done.", sourceObjective = "Glorthal Stiffbeard at Frosthold wants you to kill Sirana Iceshriek.", completion = "It's done then. Thank you.\n\nI've spoken with Fjorlin - he said that his men will take charge of keeping the harpies down a bit. As long as we don't let up again, they won't find the courage to think they can attack our people.\n\nI know this wasn't the most tasteful work - take this as a token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[12869] = { id = 12869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushed Too Far", description = "You were there with Loken, weren't you? The iron dwarves captured Veranus, the brood mother of the proto-drakes. The drakes don't seem even a little bit happy about the situation... they've gotten very aggressive.\n\nThey've pushed into stormcrest territory and the eagles have taken to an all out fight with them. It's time to return the favor. We're riding to the Foot Steppes and slaughtering them there.\n\nKing Stormheart left this hammer to me - make good use and see to it that I get it back.", sourceObjective = "Fjorlin Frostbrow at Frosthold wants you to ride with a Stormcrest Eagle and kill 16 Stormpeak Wyrms in the Foot Steppes.", progress = "This is completely out of control.", completion = "I don't see the drakes being dissuaded so easily. Stop back by tomorrow if you think you can spare more time to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[12870] = { id = 12870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Relics", description = "Why hello thar!\n\nBefore you be headin' off to do your grand questin' and adventure, might I beg a wee favor of ya, <lad/lass>?\n\nThese mountains be packed full'a precious relics and baubles... this place be a dream come true for tha league. I'd be much obliged if ya could bring any such treasures you stumble upon back ta me. You can even share in me ale for tha trouble! Trust me <lad/lass>, that's a rich deal!", sourceObjective = "Return 10 Relics of Ulduar to Rork Sharpchin in Frosthold.", progress = "Did ya find some o' dem relics for me?", completion = "Beaut! Yer a good one you are.\n\nTilt one back wi' me! Let us celebrae' this glorious find!", sourceObjectiveStatus = "unverified-source-field" }
quests[12871] = { id = 12871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid from the Explorers' League", description = "Interesting. I don't see any locking mechanisms on the shell. That suggests to me that it may take more than just finding the other piece to combine the keystone.\n\nTake the shell back to the expedition leader, Lagnus, at Frosthold. Once he gets over his awe, he should be able to glean what the core looks like based on the shell, and maybe they can get the Frost Dwarves to help find it.\n\nI'm going to see if I can find out how to combine the two pieces. We'll catch up once we've both made some progress.", sourceObjective = "Take Norgannon's Shell to Lagnus at Frosthold.", progress = "Hello there!", completion = "By Muradin's beard! Is that what I think it is?! Brann's really outdone himself this time... and you too for that matter! The boys back home are never going to believe this.", sourceObjectiveStatus = "unverified-source-field" }
quests[12872] = { id = 12872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", sourceObjective = "Recover Norgannon's Shell from Archivist Mechaton.", progress = "Well, don't just stand there, show me the shell!", completion = "That's it! That's the first half of Norgannon's keystone. Well done, {name}. When I get back to Ironforge, I'm going to have you inducted as an honorary member in the Explorers' League!", sourceObjectiveStatus = "unverified-source-field" }
quests[12873] = { id = 12873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frostborn King", description = "Definitely... I can see exactly what the core must look like. If any of the frostborn have seen it, they'll be sure to recognize the description.\n\nThere's no time to waste, let's get straight to business. Go talk to King Stormheart and request his aid... he's sure to know someone who can help us find the core. And be nice about it will you - he's very respected around here.", sourceObjective = "Speak to Yorg Stormheart in Frosthold.", completion = "Norgannon's Core? Never heard of it. I might well know someone that has though.", sourceObjectiveStatus = "unverified-source-field" }
quests[12874] = { id = 12874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fervor of the Frostborn", description = "I be more than willing ta lend my shelter and home ta travelers in need, but I'm nae too keen ta force my people inte yer affairs.\n\nI'll tell ye what... my people are warriors, straight and true. On the day a frostborn becomes a man, he has ta prove himself in battle. He has ta show us that he'll not let size hold'm back.\n\nShow me yer as strong and fierce as one of my men, and I'll have them lend ye an ear or a blade. Speak ta Fjorlin over by the cliff to the south there and he'll put ye ta the test.", sourceObjective = "Yorg Stormheart at Frosthold has requested that you speak to Fjorlin Frostbrow to secure a ride and face your challenge.", progress = "Ye've come back to me. Have ye come back to me victorious?", completion = "Ha! Grand tale lad... perhaps ye have a bit of frostborn blood in ye, eh? Yer not just talk anyway, and that's what I needed to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[12875] = { id = 12875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Experienced Guide", description = "I don't know where this core is hiding, but ye knew that. I said I'd help though, and that I shall.\n\nThere's a hermit by the name of Drom Frostgrip who lives in a cave north of here... down in tha valley. We've strayed away from the titans a bit ourselves being that there are so few about, but Drom's loyal to the old ways... he keeps an eye on their most precious places and speaks te the keeper Creteus often.\n\nYer sure to find him in the back of his cave... tell'm I sent ye and he'll help ye.", sourceObjective = "Locate Drom Frostgrip.", completion = "<Drom coughs up a bit of blood.>\n\nNorgannon's Core, eh? I've spent a fair number of days trying to find anything I could about it myself, but it seems to be one of the relics that's still guarded. With reason I suppose.\n\nIf King Stormheart sent you, he surely must see something noble in ye... and I'm not one to refuse my king.", sourceObjectiveStatus = "unverified-source-field" }
quests[12876] = { id = 12876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Guests", description = "Our scouts have spotted iron dwarves in the valley north of here. I overheard King Stormheart sending you to visit Drom and I'm admittedly a bit worried about'm.\n\nIf you find any iron dwarves when you head down there, put'm down hard and fast for me, eh? I dun think they know exactly where we are or how to get here just yet, and I'd prefer to keep it that way.", sourceObjective = "Fjorlin Frostbrow at Frosthold wants you to kill 10 Stormforged Invaders.", progress = "Were the scouts right? Were there dwarves down there?", completion = "Grim news, lad. Those iron dwarves seem to be increasing in numbers... we've been seeing them all over the mountains. I smell war coming.\n\nThank you for dealing with this bunch... a little more time bought.", sourceObjectiveStatus = "unverified-source-field" }
quests[12877] = { id = 12877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lonesome Watcher", description = "I never found the core... but I've often spoken to the keeper Creteus, and his omissions give him away. You'll find Creteus over the mountains to the east, in the Foot Steppes, keeping watch on the Engine of the Makers. The core might well be in there, but you'll need to win Creteus's favor.\n\nThe iron dwarves were here looking for something... it might well be the core. They took my ring. Find their leader, get the ring back, and show it to Creteus so that he knows I sent you.", sourceObjective = "Recover Frostgrip's Signet Ring from an Iron Dwarf Monitor and then bring it to Creteus in the Foot Steppes.", progress = "Hello, {race}.\n\nI am pleased that you have opted to utilize your tongue over your blade when making my acquaintance. I have found that a more and more rare quality among your kind of late.", completion = "Drom's ring? I am to assume Drom is not well if he did not introduce you directly. I am sorry to hear of that. Drom is a noble dwarf, if an inquisitive one.\n\nOn what business have you come then?", sourceObjectiveStatus = "unverified-source-field" }
quests[12878] = { id = 12878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Relic", description = "During your absence, I was privileged enough to parley with the dwarf Brann Bronzebeard. This dwarf indicated his purpose for seeking the keystone, and I am satisfied that it is for satisfactory intent... I believe this dwarf may be the entity for which the keystone was created.\n\nNorgannon's Core is located in the Frigid Tomb to the southeast. Its guardians are ancient beings of ice, and they will not welcome your presence. Best these guardians and retrieve the keystone with my blessing, {race}.", sourceObjective = "Creteus in the Foot Steppes has provided you with the information to locate Norgannon's Core.", completion = "<As the chest opens, air rushes out into the chamber, carrying with it the musty smell of something that has been here for countless years. Norgannon's Core rests in the bottom of the chest, undisturbed by the ages.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12879] = { id = 12879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Frostborn King", description = "<As you retrieve the core from the chest, you hear the thumping of heavy footsteps rushing towards you from the corridor. There is the faint sound of battle in the distance.>", sourceObjective = "Bring Norgannon's Core back to Creteus in the Foot Steppes.", progress = "Someone is using the Forge of Wills to create this army... Ulduar is no longer safe. {race}, did you recover the core?", completion = "Someone is using the Forge of Wills to create this army... Ulduar is no longer safe.\n\n{race}, I am pleased that you were able to reach the core before these abominations were.", sourceObjectiveStatus = "unverified-source-field" }
quests[12880] = { id = 12880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Explorer", description = "Combining the keystone will require Norgannon's Binding - a device located in the Engine of the Makers, the large pit beside us. Brann should be down there with the other half of the keystone now. I have instructed him on the use of the device. He awaits your presence.\n\nI will do what I can to keep the iron dwarves occupied, but I do not have confidence that I will hold them for long. King Stormheart is returning to the defense of Frosthold with some of his men shortly. Please hurry, {race}.", sourceObjective = "Bring Norgannon's Core to Brann Bronzebeard in the Engine of the Makers.", progress = "Hey there, lad! Good to meet ya in person. Did you find it?", completion = "You're brilliant, lad! Brilliant! This will be a glorious day indeed.\n\nQuickly, hand me the core before those iron dwarves make their way down here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12881] = { id = 12881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard" }
quests[12882] = { id = 12882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Relics", description = "Welcome to the peaks.\n\nI have a simple request before you head off on whatever grand jaunt you have planned. There are relics and treasures of ancient Ulduar scattered through these mountains. Most are likely in possession of the various sentient races.\n\nReturn any that you find to me, and I will reward you in kind. Perhaps I'll even let you partake on my many potent ales.", sourceObjective = "Return 10 Relics of Ulduar to Olut Alegut at the Grom'arsh Crash-site.", progress = "Were you able to find the relics of which I spoke?", completion = "These will do nicely! I am much obliged. Perhaps a drink for your troubles?", sourceObjectiveStatus = "unverified-source-field" }
quests[12883] = { id = 12883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders From Drakuru", description = "Minions be hearin' da call of your masta! Da Lich King be givin' Drakuru full control of da armies of da Scourge in Zul'Drak. We be commanded ta kill everyting.\n\nEVERYTING MUST DIE!\n\nWe be processin' all da corpses in da Dead Fields and sendin' em up ta Prince Navarius' crew in  Zeramas for Scourgin'! Notin' goes ta waste on Drakuru's watch!\n\nSoon we be drinkin' da blood of da prophets ta become stronger dan eva before! Zul'Drak and Gundrak gonna fall to da Scourge!", sourceObjective = "Return the Orders From Drakuru to Crusader Lord Lantinga at Light's Breach in Zul'Drak.", progress = "Drakuru, eh? I've heard the name before...", completion = "If this is the same Drakuru from Drak'Tharon Keep we are going to need... outside assistance.\n\nDeath knights of Acherus are stationed nearby, undoubtedly following the same trail of Scourge destruction that lead the Argent Crusade here. As half of our army is tied up at the Argent Stand, battling crazed Drakkari trolls, we will have to join forces with the Knights of the Ebon Blade.\n\n<Lantinga mutters under his breath.>\n\nI was hoping I'd never have to see those scoundrels again after Light's Hope...", sourceObjectiveStatus = "unverified-source-field" }
quests[12884] = { id = 12884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ebon Watch", description = "West of here, across the ruined roads and structures, is the death knight encampment of Ebon Watch.\n\n<Crusader Lord Lantinga rolls up Drakuru's orders.>\n\nTake these orders and deliver them to Stefan Vadu. He is the death knight in command at Ebon Watch. Let him know that the Argent Crusade will deal with Prince Navarius. They'll have to handle Drakuru.\n\nBe careful, {name}. The way to Ebon Watch is teeming with Scourge.", sourceObjective = "Deliver the Orders From Drakuru to Stefan Vadu at Ebon Watch in Zul'Drak.", progress = "What have you got there, {race}?", completion = "<Stefan reads the missive, then crumples it up and tosses it into the fire.>\n\nOld news. The Argent Crusade is - once again - late to the party. We've been tracking Drakuru since Grizzly Hills. He is slated for eradication.", sourceObjectiveStatus = "unverified-source-field" }
quests[12885] = { id = 12885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exiles of Ulduar", description = "The Storm Peaks are an intriguing place, but there's far more here than titan ruins. The peoples who live here face a dire threat in Loken and his minions.\n\nHe sent his favorite servants, the iron dwarves, on a brutal campaign against all the creatures of stone. He expelled the earthen from Ulduar, forcing them to take shelter at Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren are beset by the iron dwarves there. Find and help them, {name}.", sourceObjective = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the struggle for Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12886] = { id = 12886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drakkensryd", description = "This is it.  You've passed all the tests of the Hyldsmeet... all but one.  You've risen among our sisters' best and fiercest.\n\nThe final test is at hand.  The Drakkensryd - the true test of a Hyldnir's worth and warrior spirit.  It'll be you, your riding drake, a chained harpoon and a score of your sisters vying for dominance.\n\nShow no quarter.  None will be expected.", sourceObjective = "Use the Hyldnir Harpoon to defeat 10 Hyldsmeet Drakeriders at the Temple of Storms.", progress = "Begone!", completion = "Sif... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12887] = { id = 12887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur dwarves have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", sourceObjective = "Destroy The Ocular and then report to Baron Sliver at The Shadow Vault.", progress = "The Ocular still stands! Thassarian was a fool to trust you.\n\nWhoever you are, don't return again until it is destroyed. My position here must not be compromised!", completion = "Perhaps now we can really get something done. Don't be fooled though, the Lich King can still 'see' through his Scourge minions.\n\nThat's why you're here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12888] = { id = 12888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SCRAP-E", description = "This card allows the user to access the control panel of the scrapbot designated SCRAP-E, in order to perform maintenance and reprogram the bot's directives.\n\nSCRAP-E appears to be assigned to the interior of the building at The Inventor's Library. The card displays a list of the bot's broken components and failing systems. With the proper parts, the bot can be restored to working condition.", sourceObjective = "Bring the SCRAP-E Access Card along with 4 Handfuls of Cobalt Bolts and 5 Overcharged Capacitors to SCRAP-E at The Inventor's Library.", progress = "<You open SCRAP-E's access panel.>", completion = "<You begin performing the repairs indicated by the access card. When the repairs are complete, you close the access panel and throw the power switch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12889] = { id = 12889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prototype Console", description = "Designation SCRAP-E.\n\nDirective: Maintain consoles and databases of Inventor's Library in Keeper Mimir's absences.\n\nTime since last maintenance cycle: 489 days.\n\nStatus of schematic data: unknown.\n\nCurrent tasks: Repair prototype console.", sourceObjective = "Interact with the Prototype Console in The Inventor's Library.", completion = "You examine the display on the repaired prototype console. At least one of Mimir's schematics seems to have survived the long period between maintenance cycles. From the diagrams and instructions displayed in the schematic's file, you could easily construct the mechagnome shown.", sourceObjectiveStatus = "unverified-source-field" }
quests[12890] = { id = 12890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Size Mattered..." }
quests[12891] = { id = 12891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have an Idea, But First...", description = "When I was in the - ahem - employ of the Lich King, we would often use a device known as a sovereign rod to keep some of the more intelligent Scourge in line.\n\nI require that you assist me in the construction of a new one.\n\nLuckily for you, all of the necessary components are at hand: a cultist rod, an abomination hook, a geist rope, and a handful of Scourge essences.\n\nThis should not be difficult, {class}.", sourceObjective = "Baron Sliver at The Shadow Vault has asked you to collect a Cultist Rod, an Abomination Hook, a Geist Rope, and 5 Scourge Essences.", progress = "When you've managed to acquire that which I have asked of you, I will fashion the device, with a few modifications for our purposes, and we'll be on with our business.", completion = "Quickly, hand them to me and stay out of sight!\n\nThe rod, the hook, and the rope are all very self-evident in their usage when combined. I just need to infuse the result with the essences and we'll be ready to proceed.\n\nIt's all very mundane in its composition, but extraordinary in its application!", sourceObjectiveStatus = "unverified-source-field" }
quests[12892] = { id = 12892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur goblins have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", sourceObjective = "Destroy The Ocular and then report to Baron Sliver at The Shadow Vault.", progress = "The Ocular still stands! Koltira was a fool to trust you.\n\nWhoever you are, don't return again until it is destroyed. My position here must not be compromised!", completion = "Perhaps now we can really get something done. Don't be fooled though, the Lich King can still 'see' through his Scourge minions.\n\nThat's why you're here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12893] = { id = 12893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Your Mind", description = "Vile, Lady Nightswood, and The Leaper would make excellent weapons in the fight against the Lich King if they can be broken from his will. That is what the Sovereign Rod is for.\n\nYou'll find them on the ledges to the east and west of the vault, as well as on the mid-tier of the vault above us. The rod is to be used upon the corpses of the three.\n\nFly now. We will have them as our own!", sourceObjective = "Baron Sliver at the Shadow Vault wants you to use the Sovereign Rod on the corpses of Vile, Lady Nightswood, and The Leaper.", progress = "You have NOT turned them yet. Do not insult my intelligence, {class}!", completion = "We will put those three to good use once we finally take the vault.\n\nSpeaking of which....", sourceObjectiveStatus = "unverified-source-field" }
quests[12894] = { id = 12894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crusader Forward Camp", description = "Crusader Dargath, Crusader MacKellar, Engineer Reed and the twins, Gerk and Burr, were sent to the Dead Fields to establish a battle front days ago. As of my last correspondence with them, they had successfully established a camp on the border of the Dead Fields, northwest of here.\n\nIn light of this newfound information about Drakuru and Prince Navarius I think it would be prudent to send someone to the Crusader Forward Camp post-haste.\n\nPack up your belongings, {name}. You must leave at once!", sourceObjective = "Seek out Crusader MacKellar at the Crusader Forward Camp in Zul'Drak.", completion = "Everything was fine until the Scourge attacked. They took off with Dargath, Gerk and Burr and they also destroyed our ride. Guess who led that attack?\n\n<MacKellar nods.>\n\nNavarius...\n\nSeems this whole area is some type of factory for Scourge. We're in the middle of a damned undead mine field!", sourceObjectiveStatus = "unverified-source-field" }
quests[12895] = { id = 12895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Bronzebeard", description = "Before we left, I received the file Scout Vor'takh compiled on this Brann Bronzebeard. There can be no doubt that Brann was headed for the Storm Peaks from his journal entries and findings in Grizzly Hills. Before we crashed, I caught sight of a campsite south of here, across the Foot Steppes, and overlooking the frozen Bor's Breath River.\n\nIf Brann isn't there, search the camp and its environs for any clues as to where that blasted dwarf might've gone. Bring back anything you find.", sourceObjective = "Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Boktar Bloodfury at the Grom'arsh Crash-Site.", progress = "Did you have any luck finding Bronzebeard's camp?", completion = "Of course, with our luck, I probably could've predicted this. Well, we're not going to let him get away that easily. Let's see what that note says.", sourceObjectiveStatus = "unverified-source-field" }
quests[12896] = { id = 12896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", sourceObjective = "Defeat General Lightsbane and then report your success back to Thassarian aboard the gunship, The Skybreaker.", completion = "General Lightsbane and his forces are defeated? The Shadow Vault is taken?", sourceObjectiveStatus = "unverified-source-field" }
quests[12897] = { id = 12897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", sourceObjective = "Defeat General Lightsbane and then report your success back to Koltira Deathweaver aboard the gunship, Orgrim's Hammer.", completion = "General Lightsbane and his forces are defeated? The Shadow Vault is taken?", sourceObjectiveStatus = "unverified-source-field" }
quests[12898] = { id = 12898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Thassarian gazes out over the horizon.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", sourceObjective = "Report back to Baron Sliver at The Shadow Vault.", completion = "Good of you to return. As you can see, we have our hands full here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12899] = { id = 12899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Koltira gazes down at the map on the floor.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", sourceObjective = "Report back to Baron Sliver at The Shadow Vault.", completion = "Good of you to return. As you can see, we have our hands full here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12900] = { id = 12900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Harness", description = "So you want to ride?  Well, if you've made it this far someone must think you've got a shot at the Hyldsmeet.\n\nFirst things first; we'll have to make you a harness.\n\nIn the cliffs to the south, you'll find scattered groups of yeti.  Their hides are tough and just the right thickness.  Bring me some and we'll get you started on the path of the bear-rider.", sourceObjective = "Astrid Bjornrittar in Brunnhildar Village wants you to obtain 3 Icemane Yeti Hides.", progress = "Did you find the hides yet?  You'll find yeti in the hills below.", completion = "These will do nicely.  I'll have the harness ready for you in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12901] = { id = 12901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Something Out Of Nothing", description = "Prince Navarius must be stopped. We can't let the Scourge continue to use this area as a zombie factory. If we can get the tank operational we might stand a chance. What I need right now are spare parts.\n\nNorthwest of here is an area called Thrym's End. The Scourge armies are using the area as a base of sorts. Spread out across the base is the wreckage from their arrival. Bits and pieces of Scourge scrap metal litter the landscape. Get that stuff to me and I'll try and put it to good use.", sourceObjective = "Engineer Reed at Crusader Forward Camp in Zul'Drak has asked that you recover 10 pieces of Scourge Scrap Metal.", progress = "I really don't know if this plan will work, {name}. Just bring me the scrap metal and I'll do what I can.", completion = "What is this junk! Ah, damn it all! It's useless. Scourge metal isn't gonna do the trick. What are we going to do?", sourceObjectiveStatus = "unverified-source-field" }
quests[12902] = { id = 12902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search Of Answers", description = "These poor creatures are the only survivors.\n\nAccording to their chief, the Drakkari trolls and Rageclaw wolvar have been allies for thousands of years. They've been living here, alongside the trolls, for generations, completely unaware of the ever changing world around them. To the Rageclaw, a troll is a troll, so the troll attack upon their den took them by surprise.\n\nWe need some answers, {name}. Scour their village - southeast of here - for clues as to who or what is in charge of these attacks.", sourceObjective = "Search Rageclaw Den for a clue about who or what initiated the attacks against the Rageclaw Wolvar.", completion = "There is a scroll floating in the air above the strange altar. This must be what Crusader Lord Lantinga is looking for!", sourceObjectiveStatus = "unverified-source-field" }
quests[12903] = { id = 12903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's What Friends Are For...", description = "We were attacked by Prince Navarius and at least a dozen Scourge. I told Dargath and the twins to stay inside the tank, but they wouldn't listen. Dargath looked me in the eyes and said, \"If somebody doesn't get out of this tank, they'll kill us all.\" He then made Reed cut the engine and charged. Most heroic thing I've ever seen.\n\nI heard the Prince barking orders to the monsters. Sounded like he was taking them to Thrym's End, northwest of here. We have to rescue our friends. Will you go look for them?", sourceObjective = "Crusader MacKellar at Crusader Forward Camp has asked that you find Crusader Dargath, Gerk and Burr.", completion = "It was a great sacrifice that those three made and it won't soon be forgotten. Their passing will not be in vain. We will be victorious!", sourceObjectiveStatus = "unverified-source-field" }
